END $$;

-- Node 51 (A1-1.3.4) rev 10 -> 11
DO $$
DECLARE
  v_actual INT;
  v_expected INT := 10;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 51 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 51: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (51, 11, $p2b_51$[{"t": "list", "id": "a1-1-3-4-b1", "imp": "core", "items": ["1、==I/O 操作==", "（1）==输入和输出任务：I/O 操作也包括辅存与内存之间的数据传输==", "（2）==I/O 操作与CPU 的运算可同时进行（并行）==", "（3）==多个I/O 设备的操作也可同时进行工作（并行工作）==", "（4）==每类I/O 设备都有各自的控制器，它们按照CPU 的I/O 操作命令，独立地控制I/O 操作的全过程。==", "2、==I/O 接口==", "（1）==串行：一次传输1 位数据；串行的传输速度不一定小于并行的传输速度.（COM 接口，USB）==", "（2）==并行：一次传输8 位（或16 位、32 位）数据。(如LPT 接口打印机或扫描仪、DVI、MIDI、VGA)==", "（3）==独占式：只能外接1 个设备（DVI、MIDI 等）==", "（4）==总线式：可以扩展多个设备。（USB 等）==", "3、==I/O 控制器==", "（1）==I/O 控制器是用于实现CPU 对设备的控制部件。==", "（2）==I/O 控制器是控制计算机输入输出的一个最基本的控制系统，可指挥计算机的各个部件按照指令的功能要求协调工作的部件。==", "（3）组成：^^指令寄存器IR、程序计数器PC、操作控制器OC^^。", "（4）I/O 控制器的功能：", "①、^^接收 CPU 指令：CPU 的读写指令和参数存储在控制寄存器中^^", "②、^^向CPU 报告设备的状态：I/O 控制器中会有相应的状态寄存器，用于记录I/O 设备的当前状态。^^（比如1 代表设备忙碌，0 代表设备就绪）", "③、^^数据交换：数据寄存器，暂存CPU 发来的数据和设备发来的数据，之后将数据发给控制寄存器或CPU。^^", "④、^^地址识别：类似于内存的地址，为了区分设备控制器中的各个寄存器，需要给各个寄存器设置一个特定的地址。I/O 控制器通过CPU 提供的地址来判断CPU 要读写的是哪个寄存器。^^", "（5）常见I/O 控制方式：", "①、^^程序直接控制方式^^：CPU 向I/O 模块发出读写指令，CPU 会从状态寄存器中读取I/O 设备的状态，如果是忙碌状态就继续轮询检查状态，如果是已就绪，就代表I/O 设备已经准备好，可以从中读取数据到CPU 寄存器中，读到CPU 后，CPU 还要往存储器（内存）中写入数据，写完后再执行下一套指令。", "②、^^中断驱动方式^^：中断驱动方式的思想是允许I/O 设备主动打断CPU 的运行并请求服务，从而“解放”CPU，使得其向I/O 控制器发送读命令后可以继续做其他有用的工作。", "③、^^DMA（直接存储器访问）^^：DMA 方式的数据流向是从设备直接放入内存（设备→内存），或者是从内存直接到设备（内存→设备），不再使用CPU 作为中间者。", "④、^^通道控制方式^^：通道是一种硬件，可以理解为“低配版的CPU”。通道与CPU 相比的话，CPU 能够处理的指令种类比较多，而通道只能执行单一指令。使用这种控制方式，CPU 干涉频率极低，通道会根据CPU 的指令执行相应程序，只有完成一组数据块的读写后才需要发出中断信号让CPU 干预。"], "title": "", "ordered": false}, {"t": "table", "id": "a1-1-3-4-t1", "imp": "normal", "rows": [["程序直接控制方式", "CPU 发出 I/O 命令后需不断轮询状态寄存器", "极高", "字", "设备 → CPU → 内存，或内存 → CPU → 设备", "每阶段优点均解决了上一阶段最大缺点；总体演进方向是尽量减少 CPU 对 I/O 过程的干预"], ["中断驱动方式", "CPU 发出 I/O 命令后可执行其他任务，I/O 完成后设备控制器发出中断信号", "高", "字", "设备 → CPU → 内存，或内存 → CPU → 设备", "解放轮询等待，但每传送一个字仍需 CPU 中断参与"], ["DMA 方式", "CPU 发出 I/O 命令后可执行其他任务，整块传送完成后 DMA 控制器发出中断信号", "中", "块", "设备 → 内存，或内存 → 设备（不经过 CPU）", "数据直接在外设与内存间成块传输，大幅降低中断频率"], ["通道控制方式", "CPU 下达通道任务后可执行其他任务，通道执行通道程序并在一组块完成后发出中断", "低", "一组块", "设备 → 内存，或内存 → 设备", "软硬件结合执行通道指令，CPU 仅在成组数据块完成后干预一次"]], "title": "", "headers": ["I/O 控制方式", "完成一次读/写的过程", "CPU 干预频率", "每次 I/O 的数据传输单位", "数据流向", "核心优缺点与演进规律"]}, {"h": 590, "t": "img", "w": 1206, "id": "a1-1-3-4-b2", "alt": "CPU、内存与 I/O 设备之间总线控制结构示意图", "imp": "normal", "src": "/kb-assets/theory/p14_r0_98bc357e9ae42d38.png", "title": "", "caption": "主机与外设 I/O 数据传输结构及总线调度关系示意"}, {"t": "list", "id": "a1-1-3-4-b3", "imp": "core", "items": ["4、==I/O 总线及其发展==", "^^定义与任务^^：I/O 总线是计算机用于==在 I/O 设备与内存（主机）之间传输数据的部件==，由传输线路及控制器组成，主要任务是高速传输数据。", "I/O 总线连接的是 I/O 控制器，I/O 控制器提供 I/O 接口，I/O 接口再连接 I/O 设备。", "I/O 接口的作用是：连接 I/O 设备自身的控制器，实现 I/O 设备与总线、与主机的连接。", "^^性能指标^^：I/O 总线最重要的性能指标是带宽，即单位时间内可传输的最大数据量。", "5、I/O 总线带宽", "（1）==并行总线带宽(MB/s)=并行总线时钟频率(MHz)*并行总线位宽(bit/8=B)*每时钟传输几组数据(cycle)==", "==PCI== 总线位宽是32 位，总线频率33MHz，每时钟传输1 组数据，它的带宽为127.2MB/s，即1017.6Mbps。", "==PCI2.1== 总线位宽是64 位，总线频率66MHz，每时钟传输1 组数据，它的带宽为508.6MB/s，即4068.8Mbps。", "==AGP== 总线位宽是32 位，总线频率66MHz，每时钟传输1 组数据，它的带宽为254.3MB/s，即2034.4Mbps。", "==AGPPro== 总线位宽是32 位，总线频率66MHz，每时钟传输1 组数据，它的带宽为254.3MB/s，即2034.4Mbps。", "==AGPPro== 是AGP 的改进型，它使工作站级主板也能利用AGP 的加速性能，降低了AGP 所需的电压供应，并没有什么太大的改变。", "==AGP2X== 总线位宽是32 位，总线频率66MHz，每时钟传输2 组数据，它的带宽为508.6MB/s，即4068.8Mbps。", "==AGP4X== 总线位宽是32 位，总线频率66MHz，每时钟传输4 组数据，它的带宽为1017.3MB/s，即8138.4Mbps。", "==AGP8X== 总线位宽是32 位，总线频率66MHz，每时钟传输8 组数据，它的带宽为2034.6MB/s，即16276.8Mbps。", "==ISA== 总线位宽是16 位，总线频率8.3MHz，每时钟传输1 组数据，它的带宽为15.9MB/s，即127.2Mbps。", "==EISA== 总线位宽是32 位，总线频率8.3MHz，每时钟传输1 组数据，它的带宽为31.8MB/s，即254.4Mbps。", "（2）串行总线", "==串行总线带宽(MB/s)=串行总线时钟频率(MHz)*串行总线位宽(bit/8=B)*串行总线管线*编码方式*每时钟传输几组数据(cycle)==", "==PCI Express x1== 总线位宽是1 位，总线频率2500MHz，串行总线管线是1 条，每时钟传输2 组数据，编码方式为8b/10b，它的带宽为476.84MB/s，即3814.7Mbps。（带宽是PCI 的3.75 倍）", "公式是2500000000(Hz)*1/8(bit)*1(条管线)*8/10(bit)*2(每时钟传输2 组数据)=500000000B/s=476.8371582MB/s，即3814.6972656Mbps。", "==PCI Expressx2== 的带宽为953.68MB/s，即7629.4Mbps。（此模式仅用于主板内部接口而非插槽模式）", "==PCI Expressx4== 的带宽为1907.36MB/s，即15258.9Mbps。", "==PCI Expressx8== 的带宽为3814.72MB/s，即30517.8Mbps。", "==PCI Expressx16== 的带宽为7629.44MB/s，即61035.5Mbps。（带宽是AGP8X 的3.75 倍。）", "==PCI Expressx32== 的带宽为15258.88MB/s，即122071Mbps。", "==注：以下都是理论值，实际上达不到，就像实际网速与带宽一样会有差距。==", "6、==主机、外围设备与总线==：^^计算机的主机^^：==CPU、内存储器、总线等==。 计算机的外围设备：外存储器、输入设备、输出设备。", "（1）^^总线^^：==提供各部件之间相互交换各种信息的通道==。 总线按连接方式分为：前端总线（CPU 总线），连接内存和 CPU；I/O 总线（PCI 总线），连接内存与 I/O 设备。 总线传输的内容（信号）：数据信号、地址信号、控制信号。", "7、==PCI 插槽和PCI-E 插槽(PCI-E x1 和PCI-E x16)==", "==一个PCI Express 连接可以被配置成x1，x2，x4，x8，x12，x16 和x32 的数据带宽。x1 的通道能实现单向312.5MB/秒(2.5Gbit/s*1/8 位)的传输速率，同理x32 通道连接就能提供10GB/秒的速率，但考虑使用8b/10b 编码实际上有20%左右的消耗，实际的传输速率大概是8GB/S(x32 单向)。一般的显卡使用的PCI-E X16 标准，数据传输率为4.8GB/S,远远高于现在最流行的AGP 8X 的2.1GB/S 的数据流量。==", "（1）==PCI 插槽==：", "^^①、工作频率33MHz，^^", "^^②、数据线:32 位^^", "^^③、传输速率:133MB/s^^", "（2）==PCI-E x1 插槽：==", "^^①、1 个串行传输通道；^^", "^^②、最高传输速率:250MB/s^^", "（3）==PCI-E x16 插槽：==", "^^①、16 个串行传输通道；^^", "^^②、最高传输速率:5GB/s^^"], "title": "", "ordered": false}, {"h": 909, "t": "img", "w": 1295, "id": "a1-1-3-4-b4", "alt": "主板 PCI、PCI-E x1 与 PCI-E x16 扩展插槽实景标注图", "imp": "normal", "src": "/kb-assets/theory/p15_r0_269dd9c7cd7a8d1c.png", "title": "", "caption": "主板上 PCI 插槽、PCI-E x1 插槽与 PCI-E x16 显卡插槽及 CPU/内存位置标注"}, {"t": "list", "id": "a1-1-3-4-b5", "imp": "core", "items": ["8、==USB 接口==", "==（1）通用串行总线式接口==", "==（2）高速、可连接多个设备、串行传输==", "==（3）传输速率：USB1.1（1.5 MB/s）、USB2.0（60 MB/s）、USB3.0（625 MB/s）、USB3.1（1250 MB/s）、USB3.2（2500 MB/s，20 Gbps）、USB4.0（20 Gbps/40 Gbps，最高可达 5000 MB/s，采用 Type-C 接口）==", "==（4）USB2.0 使用4 线标准连接器；USB3.0 使用 9 线（9 针）标准连接器==", "==（5）使用“USB 集线器” 扩展USB 接口，最多可连接127 个设备==", "==（6）可通过USB 接口由主机向外设提供电源(+5V，100～500 mA)==", "==（7）USB 支持“即插即用”和“热插拔”。==", "==（8）图标：=="], "title": "", "ordered": false}, {"h": 226, "t": "img", "w": 467, "id": "a1-1-3-4-b6", "alt": "USB 通用串行总线及 USB 3.0 超高速标识图标", "imp": "normal", "src": "/kb-assets/theory/p16_r0_023c65ccdc4c0443.png", "title": "", "caption": "USB 标准接口图标与 USB 3.0（SS 超高速）官方认证标识对照"}, {"t": "list", "id": "a1-1-3-4-b7", "imp": "core", "items": ["==（9）可外接设备：打印机、鼠标、键盘、扫描仪等。==", "==（10）接口类型：TypeA、TypeB、TypeC 等。=="], "title": "", "ordered": false}, {"h": 639, "t": "img", "w": 1248, "id": "a1-1-3-4-b8", "alt": "USB Type-A/Type-B/Type-C/Mini/Micro 等常见接头形态及兼容对比图", "imp": "normal", "src": "/kb-assets/theory/p16_r1_70bbe554ecb0604d.png", "title": "", "caption": "USB 常见接口形态（Type-A/B/C 等）与 USB 2.0/3.0 针脚结构对比"}, {"t": "list", "id": "a1-1-3-4-b9", "imp": "core", "items": ["==（11）使用串口转换工具（器）转串口或并口。==", "==（12）相互兼容的。为了向下兼容2.0 版,USB 3.0 采用了9 针脚设计,其中四个针脚和USB 2.0 的形状、定义均完全相同,而另外5 根是专门为USB 3.0 准备的。==", "9、==其他接口==", "==（1）硬盘常用接口：IDE、SATA(e-SATA)、USB(移动硬盘)等==", "==（2）键盘和鼠标常用接口：USB、PS/2 接口等==", "==（3）网络接口：RJ-45 接口==", "==（4）显示接口：VGA、DVI(24 针)、HDMI（19 针，高清数字音频和视频接口，也称为高清多媒体接口）等==", "==（5）串口RS232:可以连接鼠标、投影仪等==", "==（6）并口：打印机、扫描仪等。==", "==（7）IEEE-1394 接口：串行方式传输，连接大量数据的音、视频设备，采用6 线连接器。==", "10、主板常见接口示例图："], "title": "", "ordered": false}, {"h": 907, "t": "img", "w": 1518, "id": "a1-1-3-4-b10", "alt": "PC 主板背部常见外设接口实景标注图（PS/2、USB、HDMI、VGA、RJ-45、音频等）", "imp": "normal", "src": "/kb-assets/theory/p17_r0_b99e11f30731a9b3.png", "title": "", "caption": "主板背部 I/O 接口实景标注：PS/2、HDMI、VGA/DVI、USB 2.0/3.0、eSATA、RJ-45 与音频口"}, {"t": "callout", "id": "a1-1-3-4-b11", "imp": "core", "kind": "tip", "text": "主机与外设通信方式：==程序查询方式（CPU 全程等待效率最低）==、==中断方式（外设就绪打断 CPU）==、==DMA 方式（直接内存访问，外设与主存成批交换数据无需 CPU 介入）==；常用总线接口包括 PCI-Express（主板内部高速点对点）、USB（热插拔串行）、SATA（硬盘串行接口）。", "title": "考向复习提示：I/O 操作方式及常用外部总线"}, {"t": "callout", "id": "a1-1-3-4-b12", "imp": "core", "kind": "trap", "text": "专转本必考趋势：传统早期采用并行接口（如打印机并口 LPT、IDE 硬盘并口）；由于高频时并行多引脚间存在严重的电磁串扰与时钟偏移，==现代高速接口全面转向采用差分信号的高速串行接口（如 PCI-E、SATA、USB、雷电）==；常考判断题误以为“并行传输速率一定快于串行”，结论完全错误！", "title": "高频易错陷阱：串行接口 vs 并行接口发展趋势"}, {"id": "a1-1-3-4-p2-sync-tip", "t": "callout", "kind": "tip", "title": "考向复习提示：2025–2026 前沿同步：USB4 v2.0、Thunderbolt 5 与 PCIe 6.0/7.0", "text": "高速串行总线取代并行总线的产业趋势持续加速（考试中仍重记 `PCI-E` / `USB 3.x` / `SATA` 串行原理）：\n• ==USB4 Version 2.0 与 Thunderbolt 5（雷电 5）==：引入全新 `PAM3` 三电平调制技术，实现 ==`80 Gbps`== 对称双向带宽与非对称显示增强最高 ==`120 Gbps`== 速率（向下兼容 `Type-C`）；英特尔雷电 5 认证还强制保障 `64 Gbps` PCIe 吞吐及最高 `240W` 供电；\n• ==PCIe 5.0 / 6.0 / 7.0 演进==：`PCIe 5.0`（`32 GT/s`）已在旗舰显卡与高速固态硬盘广泛商用；==`PCIe 6.0`==（`PAM4` 调制，`64 GT/s`，x16 双向约 `256 GB/s`）逐步落地 AI 服务器；==`PCIe 7.0`==（`128 GT/s`，x16 双向达 `512 GB/s`）规范亦已正式发布。", "imp": "core"}]$p2b_51$::jsonb, '', $p2s_51$A1-1.3.4 I/O 总线，I/O 操作方式，常用的几类 I/O 设备接口，I/O 总线带宽计算。
1、I/O 操作
（1）输入和输出任务：I/O 操作也包括辅存与内存之间的数据传输
（2）I/O 操作与CPU 的运算可同时进行（并行）
（3）多个I/O 设备的操作也可同时进行工作（并行工作）
（4）每类I/O 设备都有各自的控制器，它们按照CPU 的I/O 操作命令，独立地控制I/O 操作的全过程。
2、I/O 接口
（1）串行：一次传输1 位数据；串行的传输速度不一定小于并行的传输速度.（COM 接口，USB）
（2）并行：一次传输8 位（或16 位、32 位）数据。(如LPT 接口打印机或扫描仪、DVI、MIDI、VGA)
（3）独占式：只能外接1 个设备（DVI、MIDI 等）
（4）总线式：可以扩展多个设备。（USB 等）
3、I/O 控制器
（1）I/O 控制器是用于实现CPU 对设备的控制部件。
（2）I/O 控制器是控制计算机输入输出的一个最基本的控制系统，可指挥计算机的各个部件按照指令的功能要求协调工作的部件。
（3）组成：指令寄存器IR、程序计数器PC、操作控制器OC。
（4）I/O 控制器的功能：
①、接收 CPU 指令：CPU 的读写指令和参数存储在控制寄存器中
②、向CPU 报告设备的状态：I/O 控制器中会有相应的状态寄存器，用于记录I/O 设备的当前状态。（比如1 代表设备忙碌，0 代表设备就绪）
③、数据交换：数据寄存器，暂存CPU 发来的数据和设备发来的数据，之后将数据发给控制寄存器或CPU。
④、地址识别：类似于内存的地址，为了区分设备控制器中的各个寄存器，需要给各个寄存器设置一个特定的地址。I/O 控制器通过CPU 提供的地址来判断CPU 要读写的是哪个寄存器。
（5）常见I/O 控制方式：
①、程序直接控制方式：CPU 向I/O 模块发出读写指令，CPU 会从状态寄存器中读取I/O 设备的状态，如果是忙碌状态就继续轮询检查状态，如果是已就绪，就代表I/O 设备已经准备好，可以从中读取数据到CPU 寄存器中，读到CPU 后，CPU 还要往存储器（内存）中写入数据，写完后再执行下一套指令。
②、中断驱动方式：中断驱动方式的思想是允许I/O 设备主动打断CPU 的运行并请求服务，从而“解放”CPU，使得其向I/O 控制器发送读命令后可以继续做其他有用的工作。
③、DMA（直接存储器访问）：DMA 方式的数据流向是从设备直接放入内存（设备→内存），或者是从内存直接到设备（内存→设备），不再使用CPU 作为中间者。
④、通道控制方式：通道是一种硬件，可以理解为“低配版的CPU”。通道与CPU 相比的话，CPU 能够处理的指令种类比较多，而通道只能执行单一指令。使用这种控制方式，CPU 干涉频率极低，通道会根据CPU 的指令执行相应程序，只有完成一组数据块的读写后才需要发出中断信号让CPU 干预。
I/O 控制方式 完成一次读/写的过程 CPU 干预频率 每次 I/O 的数据传输单位 数据流向 核心优缺点与演进规律
程序直接控制方式 CPU 发出 I/O 命令后需不断轮询状态寄存器 极高 字 设备 → CPU → 内存，或内存 → CPU → 设备 每阶段优点均解决了上一阶段最大缺点；总体演进方向是尽量减少 CPU 对 I/O 过程的干预
中断驱动方式 CPU 发出 I/O 命令后可执行其他任务，I/O 完成后设备控制器发出中断信号 高 字 设备 → CPU → 内存，或内存 → CPU → 设备 解放轮询等待，但每传送一个字仍需 CPU 中断参与
DMA 方式 CPU 发出 I/O 命令后可执行其他任务，整块传送完成后 DMA 控制器发出中断信号 中 块 设备 → 内存，或内存 → 设备（不经过 CPU） 数据直接在外设与内存间成块传输，大幅降低中断频率
通道控制方式 CPU 下达通道任务后可执行其他任务，通道执行通道程序并在一组块完成后发出中断 低 一组块 设备 → 内存，或内存 → 设备 软硬件结合执行通道指令，CPU 仅在成组数据块完成后干预一次
主机与外设 I/O 数据传输结构及总线调度关系示意
4、I/O 总线及其发展
定义与任务：I/O 总线是计算机用于在 I/O 设备与内存（主机）之间传输数据的部件，由传输线路及控制器组成，主要任务是高速传输数据。
I/O 总线连接的是 I/O 控制器，I/O 控制器提供 I/O 接口，I/O 接口再连接 I/O 设备。
I/O 接口的作用是：连接 I/O 设备自身的控制器，实现 I/O 设备与总线、与主机的连接。
性能指标：I/O 总线最重要的性能指标是带宽，即单位时间内可传输的最大数据量。
5、I/O 总线带宽
（1）并行总线带宽(MB/s)=并行总线时钟频率(MHz)*并行总线位宽(bit/8=B)*每时钟传输几组数据(cycle)
PCI 总线位宽是32 位，总线频率33MHz，每时钟传输1 组数据，它的带宽为127.2MB/s，即1017.6Mbps。
PCI2.1 总线位宽是64 位，总线频率66MHz，每时钟传输1 组数据，它的带宽为508.6MB/s，即4068.8Mbps。
AGP 总线位宽是32 位，总线频率66MHz，每时钟传输1 组数据，它的带宽为254.3MB/s，即2034.4Mbps。
AGPPro 总线位宽是32 位，总线频率66MHz，每时钟传输1 组数据，它的带宽为254.3MB/s，即2034.4Mbps。
AGPPro 是AGP 的改进型，它使工作站级主板也能利用AGP 的加速性能，降低了AGP 所需的电压供应，并没有什么太大的改变。
AGP2X 总线位宽是32 位，总线频率66MHz，每时钟传输2 组数据，它的带宽为508.6MB/s，即4068.8Mbps。
AGP4X 总线位宽是32 位，总线频率66MHz，每时钟传输4 组数据，它的带宽为1017.3MB/s，即8138.4Mbps。
AGP8X 总线位宽是32 位，总线频率66MHz，每时钟传输8 组数据，它的带宽为2034.6MB/s，即16276.8Mbps。
ISA 总线位宽是16 位，总线频率8.3MHz，每时钟传输1 组数据，它的带宽为15.9MB/s，即127.2Mbps。
EISA 总线位宽是32 位，总线频率8.3MHz，每时钟传输1 组数据，它的带宽为31.8MB/s，即254.4Mbps。
（2）串行总线
串行总线带宽(MB/s)=串行总线时钟频率(MHz)*串行总线位宽(bit/8=B)*串行总线管线*编码方式*每时钟传输几组数据(cycle)
PCI Express x1 总线位宽是1 位，总线频率2500MHz，串行总线管线是1 条，每时钟传输2 组数据，编码方式为8b/10b，它的带宽为476.84MB/s，即3814.7Mbps。（带宽是PCI 的3.75 倍）
公式是2500000000(Hz)*1/8(bit)*1(条管线)*8/10(bit)*2(每时钟传输2 组数据)=500000000B/s=476.8371582MB/s，即3814.6972656Mbps。
PCI Expressx2 的带宽为953.68MB/s，即7629.4Mbps。（此模式仅用于主板内部接口而非插槽模式）
PCI Expressx4 的带宽为1907.36MB/s，即15258.9Mbps。
PCI Expressx8 的带宽为3814.72MB/s，即30517.8Mbps。
PCI Expressx16 的带宽为7629.44MB/s，即61035.5Mbps。（带宽是AGP8X 的3.75 倍。）
PCI Expressx32 的带宽为15258.88MB/s，即122071Mbps。
注：以下都是理论值，实际上达不到，就像实际网速与带宽一样会有差距。
6、主机、外围设备与总线：计算机的主机：CPU、内存储器、总线等。 计算机的外围设备：外存储器、输入设备、输出设备。
（1）总线：提供各部件之间相互交换各种信息的通道。 总线按连接方式分为：前端总线（CPU 总线），连接内存和 CPU；I/O 总线（PCI 总线），连接内存与 I/O 设备。 总线传输的内容（信号）：数据信号、地址信号、控制信号。
7、PCI 插槽和PCI-E 插槽(PCI-E x1 和PCI-E x16)
一个PCI Express 连接可以被配置成x1，x2，x4，x8，x12，x16 和x32 的数据带宽。x1 的通道能实现单向312.5MB/秒(2.5Gbit/s*1/8 位)的传输速率，同理x32 通道连接就能提供10GB/秒的速率，但考虑使用8b/10b 编码实际上有20%左右的消耗，实际的传输速率大概是8GB/S(x32 单向)。一般的显卡使用的PCI-E X16 标准，数据传输率为4.8GB/S,远远高于现在最流行的AGP 8X 的2.1GB/S 的数据流量。
（1）PCI 插槽：
①、工作频率33MHz，
②、数据线:32 位
③、传输速率:133MB/s
（2）PCI-E x1 插槽：
①、1 个串行传输通道；
②、最高传输速率:250MB/s
（3）PCI-E x16 插槽：
①、16 个串行传输通道；
②、最高传输速率:5GB/s
主板上 PCI 插槽、PCI-E x1 插槽与 PCI-E x16 显卡插槽及 CPU/内存位置标注
8、USB 接口
（1）通用串行总线式接口
（2）高速、可连接多个设备、串行传输
（3）传输速率：USB1.1（1.5 MB/s）、USB2.0（60 MB/s）、USB3.0（625 MB/s）、USB3.1（1250 MB/s）、USB3.2（2500 MB/s，20 Gbps）、USB4.0（20 Gbps/40 Gbps，最高可达 5000 MB/s，采用 Type-C 接口）
（4）USB2.0 使用4 线标准连接器；USB3.0 使用 9 线（9 针）标准连接器
（5）使用“USB 集线器” 扩展USB 接口，最多可连接127 个设备
（6）可通过USB 接口由主机向外设提供电源(+5V，100～500 mA)
（7）USB 支持“即插即用”和“热插拔”。
（8）图标：
USB 标准接口图标与 USB 3.0（SS 超高速）官方认证标识对照
（9）可外接设备：打印机、鼠标、键盘、扫描仪等。
（10）接口类型：TypeA、TypeB、TypeC 等。
USB 常见接口形态（Type-A/B/C 等）与 USB 2.0/3.0 针脚结构对比
（11）使用串口转换工具（器）转串口或并口。
（12）相互兼容的。为了向下兼容2.0 版,USB 3.0 采用了9 针脚设计,其中四个针脚和USB 2.0 的形状、定义均完全相同,而另外5 根是专门为USB 3.0 准备的。
9、其他接口
（1）硬盘常用接口：IDE、SATA(e-SATA)、USB(移动硬盘)等
（2）键盘和鼠标常用接口：USB、PS/2 接口等
（3）网络接口：RJ-45 接口
（4）显示接口：VGA、DVI(24 针)、HDMI（19 针，高清数字音频和视频接口，也称为高清多媒体接口）等
（5）串口RS232:可以连接鼠标、投影仪等
（6）并口：打印机、扫描仪等。
（7）IEEE-1394 接口：串行方式传输，连接大量数据的音、视频设备，采用6 线连接器。
