  VALUES (113, 5, $p2b_113$[{"t": "list", "id": "a3-3-5-6-b1", "imp": "core", "items": ["==力度等。==", "（2）==计算机病毒的特点∶==", "==①破坏性、==", "==②隐蔽性、==", "==③传染性、==", "==④潜伏性、==", "==⑤寄生性。==", "==（3）杀毒软件总是滞后于新病毒的出现。==", "==（4）计算机病毒既可以破坏硬件也可以破坏软件。==", "==（5）木马病毒是一种后门程序（即远程监控程序），通过互联网窃取用户的数据。==", "==（6）U 盘、软盘写保护状态下可以有效预防计算机病毒==", "==（7）可以通过邮件、光盘、磁盘、u 盘、文件、网络等传播==", "1、==凯撒密码==英文：a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z明文是加密前的字符。", "密文是加密后的字符。", "凯撒密码：", "加密：是当K=n,明文（每个字符）向后（字母表右边）偏移n 位的字符，就是密文。", "解密：是当k=m，密文（每个字符）向前（字母表左右）偏移m 位的字符，就是明文。"], "title": "", "ordered": false}, {"t": "callout", "id": "a3-3-5-6-b2", "imp": "core", "kind": "tip", "text": "现代网络安全遵循“动态纵深防御”理念，结合访问控制、身份认证、防病毒、漏洞扫描、蜜罐诱捕与审计取证技术；前沿发展趋势涵盖：==零信任架构（Zero Trust，“持续验证，永不信任”）、态势感知、云原生安全与 AI 智能威胁防御==。", "title": "考向复习提示：网络安全纵深防御体系与发展前沿"}, {"t": "callout", "id": "a3-3-5-6-b3", "imp": "core", "kind": "trap", "text": "信息安全经典铁三角（CIA 三要素）：\n• ==机密性（Confidentiality，确保信息不泄露给未授权实体）==；\n• ==完整性（Integrity，确保信息在传输和存储中未经授权不可篡改或伪造）==；\n• ==可用性（Availability，确保授权用户在需要时能正常访问服务）==；常考选择题选出不属于 CIA 基本属性的干扰项！", "title": "高频易错陷阱：信息安全三大基本属性 CIA 三要素"}, {"id": "a3-3-5-6-p2-sync-tip", "t": "callout", "kind": "tip", "title": "考向复习提示：2025–2026 前沿同步：后量子密码标准与 AI 生成内容标识国标", "text": "网络安全已从传统防病毒演进至应对量子破译风险与人工智能安全治理：\n• ==NIST 首批后量子密码（PQC）正式标准==：2024 年 8 月美国 NIST 正式发布抵御未来量子计算机解密威胁的三大标准——==`FIPS 203`（`ML-KEM`，基于格密码的通用加密密钥封装）==、==`FIPS 204`（`ML-DSA`，主推数字签名）==与 ==`FIPS 205`（`SLH-DSA`，无状态哈希备选签名）==；\n• ==我国 AI 生成内容强制标识规范（2025 年 9 月 1 日施行）==：网信办等四部门联合印发的《人工智能生成合成内容标识办法》及配套强标 ==`GB 45438-2025`== 规定：所有 AI 生成文本、图片、音频、视频必须同时嵌入让用户直观可见的==显式标识==与写入文件元数据/数字水印的==隐式标识==，严禁任何机构或个人篡改或删除标识。", "imp": "core"}]$p2b_113$::jsonb, '', $p2s_113$A3-3.5.6 威胁防范与信息安全发展趋势。
力度等。
（2）计算机病毒的特点∶
①破坏性、
②隐蔽性、
③传染性、
④潜伏性、
⑤寄生性。
（3）杀毒软件总是滞后于新病毒的出现。
（4）计算机病毒既可以破坏硬件也可以破坏软件。
（5）木马病毒是一种后门程序（即远程监控程序），通过互联网窃取用户的数据。
（6）U 盘、软盘写保护状态下可以有效预防计算机病毒
（7）可以通过邮件、光盘、磁盘、u 盘、文件、网络等传播
1、凯撒密码英文：a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z明文是加密前的字符。
密文是加密后的字符。
凯撒密码：
加密：是当K=n,明文（每个字符）向后（字母表右边）偏移n 位的字符，就是密文。
解密：是当k=m，密文（每个字符）向前（字母表左右）偏移m 位的字符，就是明文。
考向复习提示：网络安全纵深防御体系与发展前沿
现代网络安全遵循“动态纵深防御”理念，结合访问控制、身份认证、防病毒、漏洞扫描、蜜罐诱捕与审计取证技术；前沿发展趋势涵盖：零信任架构（Zero Trust，“持续验证，永不信任”）、态势感知、云原生安全与 AI 智能威胁防御。
高频易错陷阱：信息安全三大基本属性 CIA 三要素
信息安全经典铁三角（CIA 三要素）：
• 机密性（Confidentiality，确保信息不泄露给未授权实体）；
• 完整性（Integrity，确保信息在传输和存储中未经授权不可篡改或伪造）；
• 可用性（Availability，确保授权用户在需要时能正常访问服务）；常考选择题选出不属于 CIA 基本属性的干扰项！
考向复习提示：2025–2026 前沿同步：后量子密码标准与 AI 生成内容标识国标
网络安全已从传统防病毒演进至应对量子破译风险与人工智能安全治理：
• NIST 首批后量子密码（PQC）正式标准：2024 年 8 月美国 NIST 正式发布抵御未来量子计算机解密威胁的三大标准——FIPS 203（ML-KEM，基于格密码的通用加密密钥封装）、FIPS 204（ML-DSA，主推数字签名）与 FIPS 205（SLH-DSA，无状态哈希备选签名）；
• 我国 AI 生成内容强制标识规范（2025 年 9 月 1 日施行）：网信办等四部门联合印发的《人工智能生成合成内容标识办法》及配套强标 GB 45438-2025 规定：所有 AI 生成文本、图片、音频、视频必须同时嵌入让用户直观可见的显式标识与写入文件元数据/数字水印的隐式标识，严禁任何机构或个人篡改或删除标识。$p2s_113$, $p2r_113${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: A3-3.5.6 威胁防范与信息安全发展趋势。", "p1_refine_20261114", "p2_timeliness_20261114"], "pages": [66], "spans": 17}$p2r_113$::jsonb, NOW());
  UPDATE kb_entry SET published_rev = 5, updated_at = NOW() WHERE node_id = 113;
END $$;

