DO $$
DECLARE
  v_actual INT;
  v_expected INT := 3;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 165 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 165: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (165, 4, $p2b_165$[{"t": "list", "id": "b1-1-5-6-b1", "imp": "core", "items": ["1、==数据库系统及应用新技术==：自从计算机问世以来，就有了处理数据、管理数据的需求，由此，计算机技术新的研究分支——数据库技术应运而生。随着计算机应用领域的不断扩展和多媒体技术的发展，数据库已经是计算机科学技术中发展最快、应用最广泛的重要分支之一。目前，数据库技术已经相当成熟，被广泛应用于==各行各业中==，成为现代信息技术的主要组成部分，是现代计算机信息系统和计算机应用的基础和核心。", "2、==数据挖掘的概念==：数据挖掘（Data Mining）是指==从大量的数据中通过算法搜索隐藏于其中信息的过程==。数据挖掘通常与计算机科学有关，并通过统计、在线分析处理、情报检索、机器学习、专家系统（依靠过去的经验法则）和模式识别等诸多方法来实现上述目标。 数据挖掘的任务是从数据集中发现模式，可以发现的模式有很多种，按功能可以分为两大类：预测性（Predictive）模式和描述性（Descriptive）模式。在应用中往往根据模式的实际作用细分为：分类、估值、预测、相关性分析、序列、时间序列、描述和可视化等。", "3、==Variety（多样性）==：==传统的数据库中的数据基本上都是结构化数据==。不同于传统的数据库，现代企业特别是互联网企业所采集和分析的数据还包括网站日志数据、社交媒体中的文本数据、GPS（全球定位系统）所产生的位置信息、实时生成的传感器数据，甚至还有图片和视频，数据的种类和几年前相比已经有了大幅度的增加。其中，近年来爆发式增长的一些数据，如互联网上的文本数据、位置信息、传感器数据、视频等，用企业中主流的关系型数据库是很难存储的，它们都属于非结构化数据。当然，在这些种类的数据中，也有一些是过去就一直存在并保存下来的。", "4、==数据库体系结构的发展==：==DBS 运行在计算机系统之上==，其体系结构与计算机体系结构密切相关，因此 DBS 的系统结构也随着硬件和软件支撑环境的变化而不断演变。", "① ==集中式数据库系统==。早期的 DBMS 以分时操作系统作为运行环境，采用集中式的数据库系统结构，把数据库建立在本单位的主计算机上，且不与其他计算机系统进行数据交互。在这种系统中，不但数据是集中的，数据的管理也是集中的。", "5、==BigTable 分布式大规模数据库管理系统==：构建于上述两项基础之上的第三个云计算平台就是 Google 关于将数据库系统扩展到分布式平台上的 BigTable 系统。很多应用程序对于数据的组织还是非常有规则的。一般来说，数据库对于处理格式化的数据还是非常方便的，但是由于关系数据库很强的一致性要求，很难将其扩展到很大的规模。为了处理 Google 内部大量的格式化以及半格式化数据，Google 构建了弱一致性要求的分布式大规模数据库系统 BigTable。", "6、==面向对象数据库技术==：==面向对象是一种认识方法学==，也是一种新的程序设计方法学。把面向对象的方法和数据库技术结合起来，可以使数据库系统的分析、设计最大程度地与人们对客观世界的认识相一致。面向对象数据库系统是为了满足新的数据库应用需要而产生的新一代数据库系统。"], "title": "", "ordered": false}, {"t": "callout", "id": "b1-1-5-6-b2", "imp": "core", "kind": "tip", "text": "数据库新技术演进：\n• 分布式数据库（物理分散但逻辑集中统一管理）；\n• ==NoSQL 数据库四大流派：键值存储（Redis，内存高速缓存）、文档型存储（MongoDB，灵活 JSON/BSON 格式）、列族存储（HBase，海量分布式大数据）、图数据库（Neo4j，复杂社交关系网络）==；以及兼具 ACID 事务与横向扩展能力的 NewSQL。", "title": "考向复习提示：分布式数据库与 NoSQL 非关系型数据库"}, {"t": "callout", "id": "b1-1-5-6-b3", "imp": "core", "kind": "trap", "text": "专转本时政与信息技术结合热点：我国在核心基础软件领域已实现全面自主突围；==国产主流关系型数据库代表包括：华为 GaussDB、阿里 OceanBase、武汉达梦（DM）、人大金仓（KingbaseES）与中科院通用中兴 GoldenDB==；常考单选要求从选项中识别出自主研发的国产数据库产品名称！", "title": "高频易错陷阱：国之重器：自主可控国产数据库考点"}, {"id": "b1-1-5-6-p2-sync-tip", "t": "callout", "kind": "tip", "title": "考向复习提示：2025–2026 前沿同步：向量数据库与开放湖仓底座", "text": "大模型爆发推动数据库领域在传统关系型与四大 `NoSQL` 流派之外演化出关键新品类：\n• ==向量数据库（Vector Database）==：专门用于存储和毫秒级相似度检索高维语义向量的数据库，是企业级大模型实现 ==`RAG`（检索增强生成）外挂知识库与 `AI Agent` 长期记忆==的必备基础设施；\n• ^^生态双路径演进^^：既有 `Milvus`、`Qdrant` 等支撑千亿级规模与混合标量过滤的专用向量数据库；同时传统关系型数据库也纷纷内置向量引擎（最典型如 PostgreSQL 配合 ==`pgvector`== 扩展、Oracle 23ai 等）；\n• ==开放湖仓一体==：以 ==`Apache Iceberg`== 为代表的开放表格式推动数据湖与数据仓深度统一，让同一份多模态数据既能做 BI 统计，也能直接供给 AI 大模型训练。", "imp": "core"}]$p2b_165$::jsonb, '', $p2s_165$B1-1.5.6 数据库系统及应用新技术。
1、数据库系统及应用新技术：自从计算机问世以来，就有了处理数据、管理数据的需求，由此，计算机技术新的研究分支——数据库技术应运而生。随着计算机应用领域的不断扩展和多媒体技术的发展，数据库已经是计算机科学技术中发展最快、应用最广泛的重要分支之一。目前，数据库技术已经相当成熟，被广泛应用于各行各业中，成为现代信息技术的主要组成部分，是现代计算机信息系统和计算机应用的基础和核心。
2、数据挖掘的概念：数据挖掘（Data Mining）是指从大量的数据中通过算法搜索隐藏于其中信息的过程。数据挖掘通常与计算机科学有关，并通过统计、在线分析处理、情报检索、机器学习、专家系统（依靠过去的经验法则）和模式识别等诸多方法来实现上述目标。 数据挖掘的任务是从数据集中发现模式，可以发现的模式有很多种，按功能可以分为两大类：预测性（Predictive）模式和描述性（Descriptive）模式。在应用中往往根据模式的实际作用细分为：分类、估值、预测、相关性分析、序列、时间序列、描述和可视化等。
3、Variety（多样性）：传统的数据库中的数据基本上都是结构化数据。不同于传统的数据库，现代企业特别是互联网企业所采集和分析的数据还包括网站日志数据、社交媒体中的文本数据、GPS（全球定位系统）所产生的位置信息、实时生成的传感器数据，甚至还有图片和视频，数据的种类和几年前相比已经有了大幅度的增加。其中，近年来爆发式增长的一些数据，如互联网上的文本数据、位置信息、传感器数据、视频等，用企业中主流的关系型数据库是很难存储的，它们都属于非结构化数据。当然，在这些种类的数据中，也有一些是过去就一直存在并保存下来的。
4、数据库体系结构的发展：DBS 运行在计算机系统之上，其体系结构与计算机体系结构密切相关，因此 DBS 的系统结构也随着硬件和软件支撑环境的变化而不断演变。
① 集中式数据库系统。早期的 DBMS 以分时操作系统作为运行环境，采用集中式的数据库系统结构，把数据库建立在本单位的主计算机上，且不与其他计算机系统进行数据交互。在这种系统中，不但数据是集中的，数据的管理也是集中的。
5、BigTable 分布式大规模数据库管理系统：构建于上述两项基础之上的第三个云计算平台就是 Google 关于将数据库系统扩展到分布式平台上的 BigTable 系统。很多应用程序对于数据的组织还是非常有规则的。一般来说，数据库对于处理格式化的数据还是非常方便的，但是由于关系数据库很强的一致性要求，很难将其扩展到很大的规模。为了处理 Google 内部大量的格式化以及半格式化数据，Google 构建了弱一致性要求的分布式大规模数据库系统 BigTable。
6、面向对象数据库技术：面向对象是一种认识方法学，也是一种新的程序设计方法学。把面向对象的方法和数据库技术结合起来，可以使数据库系统的分析、设计最大程度地与人们对客观世界的认识相一致。面向对象数据库系统是为了满足新的数据库应用需要而产生的新一代数据库系统。
考向复习提示：分布式数据库与 NoSQL 非关系型数据库
数据库新技术演进：
• 分布式数据库（物理分散但逻辑集中统一管理）；
• NoSQL 数据库四大流派：键值存储（Redis，内存高速缓存）、文档型存储（MongoDB，灵活 JSON/BSON 格式）、列族存储（HBase，海量分布式大数据）、图数据库（Neo4j，复杂社交关系网络）；以及兼具 ACID 事务与横向扩展能力的 NewSQL。
高频易错陷阱：国之重器：自主可控国产数据库考点
专转本时政与信息技术结合热点：我国在核心基础软件领域已实现全面自主突围；国产主流关系型数据库代表包括：华为 GaussDB、阿里 OceanBase、武汉达梦（DM）、人大金仓（KingbaseES）与中科院通用中兴 GoldenDB；常考单选要求从选项中识别出自主研发的国产数据库产品名称！
考向复习提示：2025–2026 前沿同步：向量数据库与开放湖仓底座
大模型爆发推动数据库领域在传统关系型与四大 NoSQL 流派之外演化出关键新品类：
• 向量数据库（Vector Database）：专门用于存储和毫秒级相似度检索高维语义向量的数据库，是企业级大模型实现 RAG（检索增强生成）外挂知识库与 AI Agent 长期记忆的必备基础设施；
• 生态双路径演进：既有 Milvus、Qdrant 等支撑千亿级规模与混合标量过滤的专用向量数据库；同时传统关系型数据库也纷纷内置向量引擎（最典型如 PostgreSQL 配合 pgvector 扩展、Oracle 23ai 等）；
• 开放湖仓一体：以 Apache Iceberg 为代表的开放表格式推动数据湖与数据仓深度统一，让同一份多模态数据既能做 BI 统计，也能直接供给 AI 大模型训练。$p2s_165$, $p2r_165${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: B1-1.5.6 数据库系统及应用新技术。", "题库补充：数据库系统及应用新技术 (27题)", "题库补充：数据挖掘的概念 (25题)", "题库补充：Variety（多样性） (16题)", "题库补充：数据库体系结构的发展 (15题)", "题库补充：BigTable 分布式大规模数据库管理系统 (14题)", "题库补充：面向对象数据库技术 (12题)", "p1_refine_20261114", "p2_timeliness_20261114"], "pages": [102], "spans": 14}$p2r_165$::jsonb, NOW());
