  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (177, 3, $p2b_177$[{"t": "list", "id": "b2-2-3-2-b1", "imp": "core", "items": ["1、^^物联网应用难点^^：==物联网应用面临的主要难点==：^^技术标准问题：接入协议种类繁多^^，世界各国存在不同的标准。中国信息技术标准化技术委员会于 2006 年成立了无线传感器网络标准项目组；2009 年 9 月，传感器网络标准工作组正式成立 PG1（国际标准化）、PG2（标准体系与系统架构）、PG3（通信与信息交互）、PG4（协同信息处理）、PG5（标识）、PG6（安全）、PG7（接口）和 PG8（电力行业应用调研）等 8 个专项组，开展具体的国家标准制定工作。 数据安全问题：信息采集频繁，数据安全必须重点考虑。"], "title": "", "ordered": false}, {"t": "callout", "id": "b2-2-3-2-b2", "imp": "core", "kind": "tip", "text": "物联网发展方向呈现：==1. 5G/6G 与低轨卫星互联网赋能实现空天地海全域立体互联；2. 物联网与边缘人工智能深度融合演进为智能物联网（AIoT）；3. 工业互联网成为传统实体制造业数字化转型的核心基础设施==。", "title": "考向复习提示：物联网前沿发展三大未来趋势"}, {"t": "callout", "id": "b2-2-3-2-b3", "imp": "core", "kind": "trap", "text": "由于物联网底层感知终端数量极其庞大、物理分布高度分散、且往往计算资源极度受限（无法部署复杂的高强度密码算法），导致==物联网设备极易被黑客物理接触窃取或入侵组装成大规模“僵尸网络（Botnet，如 Mirai 病毒控制智能摄像头发起千万级 DDoS 攻击）”瘫痪互联网==；安全加固是物联网面临的首要生命线！", "title": "高频易错陷阱：物联网面临的巨大安全与隐私风险挑战"}, {"id": "b2-2-3-2-p2-sync-tip", "t": "callout", "kind": "tip", "title": "考向复习提示：2025–2026 前沿同步：5G RedCap 与星闪协同组网趋势", "text": "结合近年产业落地，物联网接入技术正清晰分化出高性价比协同格局：\n• ==蜂窝广域中速主力 `5G RedCap`（轻量化 5G）==：精准填补了传统昂贵高速 5G 与极低速 `NB-IoT` 之间的能力空白，在功耗和模组成本大幅下降的同时保留 5G 网络切片与低时延特性，==2025–2026 年在工业网关、电力监控与智能穿戴领域全面规模商用==；\n• ==广域 + 短距黄金组合==：产业界正广泛以 `5G RedCap`（负责广域回传）协同 ==星闪 `NearLink`==（负责局部设备高并发微秒级交互），进一步延伸至无人机与低空经济感知终端。", "imp": "core"}]$p2b_177$::jsonb, '', $p2s_177$B2-2.3.2 物联网技术未来发展趋势。
1、物联网应用难点：物联网应用面临的主要难点：技术标准问题：接入协议种类繁多，世界各国存在不同的标准。中国信息技术标准化技术委员会于 2006 年成立了无线传感器网络标准项目组；2009 年 9 月，传感器网络标准工作组正式成立 PG1（国际标准化）、PG2（标准体系与系统架构）、PG3（通信与信息交互）、PG4（协同信息处理）、PG5（标识）、PG6（安全）、PG7（接口）和 PG8（电力行业应用调研）等 8 个专项组，开展具体的国家标准制定工作。 数据安全问题：信息采集频繁，数据安全必须重点考虑。
考向复习提示：物联网前沿发展三大未来趋势
物联网发展方向呈现：1. 5G/6G 与低轨卫星互联网赋能实现空天地海全域立体互联；2. 物联网与边缘人工智能深度融合演进为智能物联网（AIoT）；3. 工业互联网成为传统实体制造业数字化转型的核心基础设施。
高频易错陷阱：物联网面临的巨大安全与隐私风险挑战
由于物联网底层感知终端数量极其庞大、物理分布高度分散、且往往计算资源极度受限（无法部署复杂的高强度密码算法），导致物联网设备极易被黑客物理接触窃取或入侵组装成大规模“僵尸网络（Botnet，如 Mirai 病毒控制智能摄像头发起千万级 DDoS 攻击）”瘫痪互联网；安全加固是物联网面临的首要生命线！
考向复习提示：2025–2026 前沿同步：5G RedCap 与星闪协同组网趋势
结合近年产业落地，物联网接入技术正清晰分化出高性价比协同格局：
• 蜂窝广域中速主力 5G RedCap（轻量化 5G）：精准填补了传统昂贵高速 5G 与极低速 NB-IoT 之间的能力空白，在功耗和模组成本大幅下降的同时保留 5G 网络切片与低时延特性，2025–2026 年在工业网关、电力监控与智能穿戴领域全面规模商用；
• 广域 + 短距黄金组合：产业界正广泛以 5G RedCap（负责广域回传）协同 星闪 NearLink（负责局部设备高并发微秒级交互），进一步延伸至无人机与低空经济感知终端。$p2s_177$, $p2r_177${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: B2-2.3.2 物联网技术未来发展趋势。", "题库补充：物联网应用难点 (6题)", "p2_timeliness_20261114"], "pages": [111], "spans": 5}$p2r_177$::jsonb, NOW());
  UPDATE kb_entry SET published_rev = 3, updated_at = NOW() WHERE node_id = 177;
END $$;

-- Node 182 (B3-3.1.4) rev 4 -> 5
DO $$
DECLARE
  v_actual INT;
  v_expected INT := 4;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 182 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 182: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (182, 5, $p2b_182$[{"t": "list", "id": "b3-3-1-4-b1", "imp": "core", "items": ["1、==5G 关键技术==5G 网络作为第五代移动通信网络，具有超高带宽、超多连接、超低时延（毫秒级的端到端时延）三大特性。", "==（1）网络切片：==", "^^①、网络面向不同的应用场景，大速率、低时延、海量连接、高可靠性等，将网络切割成满足不同需求的虚拟子网络。^^", "^^②、每个虚拟子网络的移动性、安全性、时延、可靠性，甚至计费方式等都不一样，相互之间逻辑独立，形成“网络切片”。^^", "^^③、实现网络切片的关键技术是NFV(Network  Function Virtualization 网络功能虚拟化) 和SDN(Software Defined  Network 软件定义网络)。^^", "==（2）毫米波==", "==①、无线传输速率的提升一般通过增加频谱的利用率或增加频谱的带宽来实现，毫米波技术属于后者。==", "==②、毫米波指波长在1～10 毫米的电磁波，频率处于30GHz～300GHz 的区间==", "==③、大致位于微波与远红外波相交叠的波长范围，因而兼具两种波谱的特点。==", "==（3）小基站==", "==①、毫米波技术的缺陷是穿透力差、衰减大，因此要让毫米波频段下的5G 通信在高楼林立的环境下传输并不容易，而小基站将解决这一问题。==", "==②、因为毫米波的频率很高、波长很短，意味着其天线尺寸可以做得很小，这是部署小基站的基础。==", "==③、小基站不仅在规模（指的是单个）上小于大基站，功耗也大为降低。但是需要的基站数目要比4G 的多。==", "==（4） Massive MIMO（大规模天线）：==", "==①、4G 基站只有十几根天线，但5G 基站可以支持上百根天线。==", "==②、这些天线通过Massive  MIMO 技术形成大规模天线阵列，可以同时向更多的用户发送和接收信号，从而将移动网络的容量提升数十倍甚至更大。==", "（5）==波束成形==", "^^①、Massive  MIMO 技术为5G 大幅增加容量的同时，其多天线的特点也势必会带来更多的干扰，波束成形是解决这一问题的关键。^^", "^^②、通过有效地控制这些天线，使它发出的电磁波在空间上互相抵消或者增强就可以形成一个很窄的波束，^^", "^^③、从而使有限的能量集中在特定方向上传输，不仅传输距离更远，而且还避免了信号的干扰。^^", "^^④、波束成形还可以提升频谱的利用率，通过这一技术我们可以同时从多个天线传输更多的信息。^^", "^^⑤、波束成形可以解决毫米波信号被障碍物阻挡、远距离衰减的问题。^^", "（6）==全双工==", "==①、5G 的另一大特色是全双工技术。==", "==②、全双工技术是指设备的发射机和接收机占用相同的频率资源同时进行工作，使得通信的两端同时在上、下行使用相同的频率，突破了现有的频分双工(FDD)和时分双工(TDD)模式下的半双工缺陷，这是通信节点实现双向通信的关键之一，也是5G 所需的高吞吐量和低延迟的关键技术。==", "2、==5G的三大应用场景==：5G的三大应用场景指eMBB（增强移动宽带）、mMTC（海量机器类通信）、URLLC（超可靠低时延通信）。", "3、==ITU定义的5G三大应用场景==：==国际电信联盟（ITU）定义了5G的三大类应用场景：==", "- ^^eMBB^^：==3D/超高清视频等大流量移动宽带业务==。", "- ^^mMTC^^：==大规模物联网业务==。", "- ^^URLLC^^：==无人驾驶、工业自动化等需要低时延、高可靠连接的业务==。", "4、==5G关键技术和主要优势==：^^5G的关键技术包括^^：基于OFDM优化的波形和多址接入、实现可扩展的OFDM间隔参数配置、OFDM加窗提高多路传输效率、灵活的框架设计、超密集异构网络、网络的自组织、网络切片、内容分发网络、设备到设备通信、边缘计算、软件定义网络和网络虚拟化。 主要优势：高速率、泛在网、低能耗、低时延、万物互联、重构安全。", "5、==5G主要优势及应用场景==：==作为新一代信息通信发展的主要方向==，5G将渗透到未来社会的各个领域，以用户为中心构建全方位的信息生态系统。面向2020年及未来，5G将解决多样化应用场景下差异化性能指标带来的挑战，不同应用场景面临的性能挑战有所不同，用户体验速率、流量密度、时延、能效和连接数都可能成为不同场景的挑战性指标。从移动互联网和物联网的主要应用场景、业务需求及挑战出发，5G技术主要应用场景可归纳为（也即主要优势）：连续广域覆盖、热点高容量、低功耗大连接和低时延高可靠四个主要技术场景。", "6、==新型多天线传输==：多天线技术经历了从无源到有源、从二维（2D）到三维（3D）、从高阶MIMO到大规模阵列的发展，有望实现频谱效率提升数十倍甚至更高，是目前5G技术重要的研究方向之一。 由于引入了有源天线阵列，基站侧可支持的协作天线数量将达到128根。此外，原来的2D天线阵列拓展成为3D天线阵列，形成新颖的3D-MIMO技术，支持多用户波束智能赋型，减少用户间干扰；结合高频段毫米波技术，将进一步改善无线信号覆盖性能。", "7、^^5G的容量、标准版本与使用频段^^：^^5G的容量是4G的1000倍^^，峰值速率10Gbps~20Gbps；4G为100Mb/s，5G比4G快达100倍。5G发展的主要驱动力是移动互联网和物联网。 5G标准方面，2017年R15版本协议主要聚焦增强型移动宽带eMBB业务场景；2020年R16（第二版规范）对大规模物联网mMTC、高可靠低时延通信uRLLC（超可靠低延迟通信）业务场景的技术标准进行了定义。 5G使用FR1：450MHz~6000MHz（Sub-6GHz）为低频频段，是主要使用频段；FR2为毫米波高频频段，24250MHz~52600MHz范围属于扩展频段。"], "title": "", "ordered": false}, {"t": "callout", "id": "b3-3-1-4-b2", "imp": "core", "kind": "tip", "text": "国际电信联盟（ITU）定义 5G 三大业务场景：\n1. ==eMBB（增强移动宽带）==：峰值理论速率达 ==20 Gbps==，体验速率 100 Mbps 以上（高清 VR/4K 直播）；\n2. ==uRLLC（超高可靠低时延通信）==：端到端空口时延低至 ==1 毫秒（1 ms）==，可靠性达 99.999%（自动驾驶、远程手术）；\n3. ==mMTC（海量机器类通信）==：连接密度达 ==每平方公里 100 万个连接设备==（智慧城市、海量物联网）。", "title": "考向复习提示：5G 三大核心应用场景三大技术指标（ITU 标准）"}, {"t": "callout", "id": "b3-3-1-4-b3", "imp": "core", "kind": "trap", "text": "专转本真题高频单选匹配：\n• 自动驾驶汽车紧急避障、工业机器人高精度控制、远程遥控手术，对应的是==“超高可靠低时延 uRLLC”==（对时延要求极度苛刻）；\n• 智能水表电表自动抄表、农田墒情自动回传，对应的是==“海量机器类通信 mMTC”==（连接数极大但传输数据极小）；考试常对调三大缩写场景！", "title": "高频易错陷阱：5G 三大应用场景与实际业务对应混淆"}, {"id": "b3-3-1-4-p2-sync-5ga-tip", "t": "callout", "kind": "tip", "title": "考向复习提示：2025–2026 前沿同步：5G-Advanced（5.5G）与 6G 标准化进程", "text": "应试基础仍以 ITU 定义的 5G 三大场景（`eMBB`、`uRLLC`、`mMTC`）与 `R15/R16` 为核心；近年通信标准时间表已持续推进：\n• ==5G-Advanced（5G-A / 5.5G）==：对应 `3GPP` ==`Release 18`（2024 年冻结）与 `Release 19`（2025 年 12 月正式冻结）==，在 **2025–2026 年**进入全国广泛商用，引入上下行超宽带、非地面卫星直连（`NTN`）与==通感一体化（ISAC）==；\n• ==6G 愿景与最新时间表==：国际电联（ITU）已确立 `6G` 的 ==`IMT-2030` 六大场景==——在 5G 三大场景基础上新增 ==AI 与通信融合、感知与通信融合（ISAC）、泛在空天地一体连接==；`3GPP` 已在 `Release 20` 开展 `6G` 技术研究，规划通过 `Release 21` 推出首个规范版本，全球商用目标约为 ==2030 年前后==。", "imp": "core"}, {"id": "b3-3-1-4-p2-low-alt-tip", "t": "callout", "kind": "tip", "title": "考向复习提示：2025–2026 热点科普：低空经济与 `5G-A` 通感一体及低空智联网", "text": "==低空经济==已被定位为我国国家新兴支柱产业，新修订的《中华人民共和国民用航空法》亦于 ==2026 年 7 月 1 日==起正式施行，系统规范无人驾驶航空器适航与分级管理：\n• ==核心飞行器与场景==：涵盖成熟商用的工业级无人机（农林植保、电力/航道巡检、物流配送、应急救援）以及进入适航取证与试点运营期的 ==`eVTOL`（电动垂直起降飞行器，探索城市空中交通短途通勤）==，深圳、广州、重庆、武汉、成都等地已积极开展低空示范航线；\n• ==通信信息技术支撑——低空智联网==：传统地面基站天线主要面向地面覆盖，难以监管高空高频次飞行器；依托 ==`5G-A` 基站通感一体化技术==，同一座基站通信天馈可在保持高速图传与飞控通信的同时兼备类似雷达的主动探测能力，==实时精准追踪低空无人机、飞鸟的飞行轨迹、速度与高度==，并与北斗高精度定位、数字空域图融合打造低空监管调度一张网，破解黑飞监管与安全冲突难题。", "imp": "core"}]$p2b_182$::jsonb, '', $p2s_182$B3-3.1.4 5G 关键技术和主要优势。
1、5G 关键技术5G 网络作为第五代移动通信网络，具有超高带宽、超多连接、超低时延（毫秒级的端到端时延）三大特性。
（1）网络切片：
①、网络面向不同的应用场景，大速率、低时延、海量连接、高可靠性等，将网络切割成满足不同需求的虚拟子网络。
②、每个虚拟子网络的移动性、安全性、时延、可靠性，甚至计费方式等都不一样，相互之间逻辑独立，形成“网络切片”。
③、实现网络切片的关键技术是NFV(Network  Function Virtualization 网络功能虚拟化) 和SDN(Software Defined  Network 软件定义网络)。
（2）毫米波
①、无线传输速率的提升一般通过增加频谱的利用率或增加频谱的带宽来实现，毫米波技术属于后者。
②、毫米波指波长在1～10 毫米的电磁波，频率处于30GHz～300GHz 的区间
③、大致位于微波与远红外波相交叠的波长范围，因而兼具两种波谱的特点。
（3）小基站
①、毫米波技术的缺陷是穿透力差、衰减大，因此要让毫米波频段下的5G 通信在高楼林立的环境下传输并不容易，而小基站将解决这一问题。
②、因为毫米波的频率很高、波长很短，意味着其天线尺寸可以做得很小，这是部署小基站的基础。
③、小基站不仅在规模（指的是单个）上小于大基站，功耗也大为降低。但是需要的基站数目要比4G 的多。
（4） Massive MIMO（大规模天线）：
①、4G 基站只有十几根天线，但5G 基站可以支持上百根天线。
②、这些天线通过Massive  MIMO 技术形成大规模天线阵列，可以同时向更多的用户发送和接收信号，从而将移动网络的容量提升数十倍甚至更大。
（5）波束成形
①、Massive  MIMO 技术为5G 大幅增加容量的同时，其多天线的特点也势必会带来更多的干扰，波束成形是解决这一问题的关键。
②、通过有效地控制这些天线，使它发出的电磁波在空间上互相抵消或者增强就可以形成一个很窄的波束，
③、从而使有限的能量集中在特定方向上传输，不仅传输距离更远，而且还避免了信号的干扰。
④、波束成形还可以提升频谱的利用率，通过这一技术我们可以同时从多个天线传输更多的信息。
⑤、波束成形可以解决毫米波信号被障碍物阻挡、远距离衰减的问题。
（6）全双工
①、5G 的另一大特色是全双工技术。
②、全双工技术是指设备的发射机和接收机占用相同的频率资源同时进行工作，使得通信的两端同时在上、下行使用相同的频率，突破了现有的频分双工(FDD)和时分双工(TDD)模式下的半双工缺陷，这是通信节点实现双向通信的关键之一，也是5G 所需的高吞吐量和低延迟的关键技术。
2、5G的三大应用场景：5G的三大应用场景指eMBB（增强移动宽带）、mMTC（海量机器类通信）、URLLC（超可靠低时延通信）。
3、ITU定义的5G三大应用场景：国际电信联盟（ITU）定义了5G的三大类应用场景：
- eMBB：3D/超高清视频等大流量移动宽带业务。
- mMTC：大规模物联网业务。
- URLLC：无人驾驶、工业自动化等需要低时延、高可靠连接的业务。
4、5G关键技术和主要优势：5G的关键技术包括：基于OFDM优化的波形和多址接入、实现可扩展的OFDM间隔参数配置、OFDM加窗提高多路传输效率、灵活的框架设计、超密集异构网络、网络的自组织、网络切片、内容分发网络、设备到设备通信、边缘计算、软件定义网络和网络虚拟化。 主要优势：高速率、泛在网、低能耗、低时延、万物互联、重构安全。
5、5G主要优势及应用场景：作为新一代信息通信发展的主要方向，5G将渗透到未来社会的各个领域，以用户为中心构建全方位的信息生态系统。面向2020年及未来，5G将解决多样化应用场景下差异化性能指标带来的挑战，不同应用场景面临的性能挑战有所不同，用户体验速率、流量密度、时延、能效和连接数都可能成为不同场景的挑战性指标。从移动互联网和物联网的主要应用场景、业务需求及挑战出发，5G技术主要应用场景可归纳为（也即主要优势）：连续广域覆盖、热点高容量、低功耗大连接和低时延高可靠四个主要技术场景。
6、新型多天线传输：多天线技术经历了从无源到有源、从二维（2D）到三维（3D）、从高阶MIMO到大规模阵列的发展，有望实现频谱效率提升数十倍甚至更高，是目前5G技术重要的研究方向之一。 由于引入了有源天线阵列，基站侧可支持的协作天线数量将达到128根。此外，原来的2D天线阵列拓展成为3D天线阵列，形成新颖的3D-MIMO技术，支持多用户波束智能赋型，减少用户间干扰；结合高频段毫米波技术，将进一步改善无线信号覆盖性能。
7、5G的容量、标准版本与使用频段：5G的容量是4G的1000倍，峰值速率10Gbps~20Gbps；4G为100Mb/s，5G比4G快达100倍。5G发展的主要驱动力是移动互联网和物联网。 5G标准方面，2017年R15版本协议主要聚焦增强型移动宽带eMBB业务场景；2020年R16（第二版规范）对大规模物联网mMTC、高可靠低时延通信uRLLC（超可靠低延迟通信）业务场景的技术标准进行了定义。 5G使用FR1：450MHz~6000MHz（Sub-6GHz）为低频频段，是主要使用频段；FR2为毫米波高频频段，24250MHz~52600MHz范围属于扩展频段。
考向复习提示：5G 三大核心应用场景三大技术指标（ITU 标准）
国际电信联盟（ITU）定义 5G 三大业务场景：
1. eMBB（增强移动宽带）：峰值理论速率达 20 Gbps，体验速率 100 Mbps 以上（高清 VR/4K 直播）；
2. uRLLC（超高可靠低时延通信）：端到端空口时延低至 1 毫秒（1 ms），可靠性达 99.999%（自动驾驶、远程手术）；
3. mMTC（海量机器类通信）：连接密度达 每平方公里 100 万个连接设备（智慧城市、海量物联网）。
高频易错陷阱：5G 三大应用场景与实际业务对应混淆
专转本真题高频单选匹配：
• 自动驾驶汽车紧急避障、工业机器人高精度控制、远程遥控手术，对应的是“超高可靠低时延 uRLLC”（对时延要求极度苛刻）；
• 智能水表电表自动抄表、农田墒情自动回传，对应的是“海量机器类通信 mMTC”（连接数极大但传输数据极小）；考试常对调三大缩写场景！
考向复习提示：2025–2026 前沿同步：5G-Advanced（5.5G）与 6G 标准化进程
应试基础仍以 ITU 定义的 5G 三大场景（eMBB、uRLLC、mMTC）与 R15/R16 为核心；近年通信标准时间表已持续推进：
• 5G-Advanced（5G-A / 5.5G）：对应 3GPP Release 18（2024 年冻结）与 Release 19（2025 年 12 月正式冻结），在 **2025–2026 年**进入全国广泛商用，引入上下行超宽带、非地面卫星直连（NTN）与通感一体化（ISAC）；
• 6G 愿景与最新时间表：国际电联（ITU）已确立 6G 的 IMT-2030 六大场景——在 5G 三大场景基础上新增 AI 与通信融合、感知与通信融合（ISAC）、泛在空天地一体连接；3GPP 已在 Release 20 开展 6G 技术研究，规划通过 Release 21 推出首个规范版本，全球商用目标约为 2030 年前后。
考向复习提示：2025–2026 热点科普：低空经济与 5G-A 通感一体及低空智联网
低空经济已被定位为我国国家新兴支柱产业，新修订的《中华人民共和国民用航空法》亦于 2026 年 7 月 1 日起正式施行，系统规范无人驾驶航空器适航与分级管理：
• 核心飞行器与场景：涵盖成熟商用的工业级无人机（农林植保、电力/航道巡检、物流配送、应急救援）以及进入适航取证与试点运营期的 eVTOL（电动垂直起降飞行器，探索城市空中交通短途通勤），深圳、广州、重庆、武汉、成都等地已积极开展低空示范航线；
• 通信信息技术支撑——低空智联网：传统地面基站天线主要面向地面覆盖，难以监管高空高频次飞行器；依托 5G-A 基站通感一体化技术，同一座基站通信天馈可在保持高速图传与飞控通信的同时兼备类似雷达的主动探测能力，实时精准追踪低空无人机、飞鸟的飞行轨迹、速度与高度，并与北斗高精度定位、数字空域图融合打造低空监管调度一张网，破解黑飞监管与安全冲突难题。$p2s_182$, $p2r_182${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: B3-3.1.4 5G 关键技术和主要优势。", "题库补充：5G的三大应用场景 (19题)", "题库补充：ITU定义的5G三大应用场景 (13题)", "题库补充：5G关键技术和主要优势 (13题)", "题库补充：5G主要优势及应用场景 (12题)", "题库补充：新型多天线传输 (10题)", "题库补充：5G的容量、标准版本与使用频段 (7题)", "p1_refine_20261114", "p2_timeliness_20261114"], "pages": [112], "spans": 49}$p2r_182$::jsonb, NOW());
