  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (227, 4, $p2b_227$[{"t": "list", "id": "b6-6-3-3-b1", "imp": "core", "items": ["1、==人工智能未来发展趋势==", "（1） ==AI 于各行业垂直领域应用具有巨大的潜力==：零售、交通运输和自动化、制造业及农业等各行业垂直领域具有巨大的潜力。", "（2） ==AI 导入医疗保健行业维持高速成长==：由于医疗保健行业大量使用大数据及人工智能，进而精准改善疾病诊断、医疗人员与患者之间人力的不平衡、降低医疗成本、促进跨行业合作关系。", "（3） ==AI 取代屏幕成为新UI/UX 接口==：随着智能喇叭(SmartSpeaker)、虚拟/增强现实(VR/AR)与自动驾驶车系统陆续进入人类生活环境，加速在不需要屏幕的情况下，人们也能够很轻松自在与运算系统沟通。", "（4）==未来手机芯片一定内建AI 运算核心==：现阶段主流的ARM 架构处理器速度不够快，若要进行大量的图像运算仍嫌不足，所以未来的手机芯片一定会内建AI 运算核心。", "（5） ==AI 芯片关键在于成功整合软硬件==： AI 芯片的核心是半导体及算法。", "（6） ==AI 自主学习是终极目标==： AI“大脑”变聪明是分阶段进行，从机器学习进化到深度学习，再进化至自主学习。", "（7）==最完美的架构是把CPU 和GPU(或其他处理器)结合起来==：未来，还会推出许多专门的领域所需的超强性能的处理器，但是CPU 是通用于各种设备，什么场景都可以适用。", "（8） ==AR 成为AI 的眼睛，两者是互补、不可或缺==：未来的AI 需要AR，未来的AR 也需要AI，可以将AR 比喻成AI 的眼睛。", "2、==按能力划分的三类人工智能==：人工智能可以分为==“弱人工智能”“强人工智能”和“超人工智能”三类==。", "3、==从“人工+智能”向自主智能系统发展==：==当前人工智能领域的大量研究集中在深度学习==，但是深度学习的局限是需要大量人工干预，比如人工设计深度神经网络模型、人工设定应用场景、人工采集和标注大量训练数据、用户需要人工适配智能系统等，非常费时费力。因此，科研人员开始关注减少人工干预的自主智能方法，提高机器智能对环境的自主学习能力。例如阿尔法狗系统的后续版本阿尔法元从零开始，通过自我对弈强化学习实现围棋、国际象棋、日本将棋的“通用棋类人工智能”。在人工智能系统的自动化设计方面，2017年谷歌提出的自动化学习系统（AutoML）试图通过自动创建机器学习系统降低人员成本。", "4、==人工智能领域的国际竞争将日益激烈==：当前，人工智能领域的国际竞赛已经拉开帷幕，并且将日趋白热化。2018年4月，欧盟委员会计划2018—2020年在人工智能领域投资240亿美元；法国总统在2018年5月宣布《法国人工智能战略》，目的是迎接人工智能发展的新时代，使法国成为人工智能强国；2018年6月，日本《未来投资战略2018》重点推动物联网建设和人工智能的应用。", "5、==从专用智能向通用智能发展==：==如何实现从专用人工智能向通用人工智能的跨越式发展==，既是下一代人工智能发展的必然趋势，也是研究与应用领域的重大挑战。2016年10月，美国国家科学技术委员会发布《国家人工智能研究与发展战略计划》，提出在美国的人工智能长期发展策略中要着重研究通用人工智能。阿尔法狗系统开发团队创始人戴密斯·哈萨比斯提出朝着“创造解决世界上一切问题的通用人工智能”这一目标前进。微软在2017年成立了通用人工智能实验室，众多感知、学习、推理、自然语言理解等方面的科学家参与其中。", "6、==从人工智能向人机混合智能发展==：借鉴脑科学和认知科学的研究成果是人工智能的一个重要研究方向。人机混合智能旨在将人的作用或认知模型引入人工智能系统中，提升人工智能系统的性能，使人工智能成为人类智能的自然延伸和拓展，通过人机协同更加高效地解决复杂问题。在我国新一代人工智能规划和美国脑计划中，人机混合智能都是重要的研发方向。", "7、==人工智能主要应用领域==：人工智能主要应用于==手机、APP、各种智能穿戴设备==，以及医疗、教育、金融行业、重工制造业等领域。"], "title": "", "ordered": false}, {"t": "callout", "id": "b6-6-3-3-b2", "imp": "normal", "kind": "tip", "text": "人工智能迎来生成式 AI（AIGC）历史拐点，以 ChatGPT、DeepSeek 为代表的基于 Transformer 架构的海量参数大语言模型（LLM），展现出惊人的上下文理解、常识推理、代码编写与多模态（文生图/文生视频，如 Sora）创造力；驱动人机交互迈向新纪元。", "title": "考向复习提示：生成式人工智能（AIGC）与大语言模型趋势"}, {"t": "callout", "id": "b6-6-3-3-b3", "imp": "core", "kind": "trap", "text": "专转本前沿科技常考考点：生成式大语言模型的底层原理是基于概率统计预测“下一个词出现的概率”，因此==大模型并不真正理解事实逻辑，它会言之凿凿、语调自信地编造完全虚构的虚假事实、伪造不存在的书籍文献，这种现象在学术界被称为“AI 幻觉（Hallucination）”==；因此严肃领域必须引入检索增强生成（RAG）进行知识纠偏！", "title": "高频易错陷阱：大语言模型的“幻觉（Hallucination）”现象与科技伦理"}, {"id": "b6-6-3-3-p2-sync-tip", "t": "callout", "kind": "tip", "title": "考向复习提示：2025–2026 前沿同步：AI Agent、MCP 协议与具身智能", "text": "紧扣 **2025–2026 年**产业界三大核心关键词拓展认知（同时衔接教材 AI 伦理与合规考察）：\n• ==`AI Agent`（自主智能体）==：AI 正从被动问答工具升级为具备长期记忆、自主拆解长任务、自动纠错与多智能体协同的生产力主力；\n• ==`MCP` 协议（Model Context Protocol，模型上下文协议）==：最初由 Anthropic 推出并于 2025 年底捐赠给 Linux 基金会旗下开源组织，被誉为 AI 智能体连接外部数据库、本地文件与企业 API 的 ==`USB-C` 式统一标准接口==；\n• ==具身智能（`Embodied AI`）==：结合视觉-语言-动作（`VLA`）模型与世界模型，让大模型大脑真正装入人形机器人、四足机器人与工业机器人的物理身体，并在 **2026 年**迈入工业分拣、巡检及服务量产试点拐点；\n• ^^法规底线合规^^：在公开发布生成式 AI 作品时，须严格遵守 2025 年 9 月 1 日施行的 ==`GB 45438-2025`== 显式与隐式内容标识强制要求。", "imp": "core"}]$p2b_227$::jsonb, '', $p2s_227$B6-6.3.3 人工智能未来发展趋势。
1、人工智能未来发展趋势
（1） AI 于各行业垂直领域应用具有巨大的潜力：零售、交通运输和自动化、制造业及农业等各行业垂直领域具有巨大的潜力。
（2） AI 导入医疗保健行业维持高速成长：由于医疗保健行业大量使用大数据及人工智能，进而精准改善疾病诊断、医疗人员与患者之间人力的不平衡、降低医疗成本、促进跨行业合作关系。
（3） AI 取代屏幕成为新UI/UX 接口：随着智能喇叭(SmartSpeaker)、虚拟/增强现实(VR/AR)与自动驾驶车系统陆续进入人类生活环境，加速在不需要屏幕的情况下，人们也能够很轻松自在与运算系统沟通。
（4）未来手机芯片一定内建AI 运算核心：现阶段主流的ARM 架构处理器速度不够快，若要进行大量的图像运算仍嫌不足，所以未来的手机芯片一定会内建AI 运算核心。
（5） AI 芯片关键在于成功整合软硬件： AI 芯片的核心是半导体及算法。
（6） AI 自主学习是终极目标： AI“大脑”变聪明是分阶段进行，从机器学习进化到深度学习，再进化至自主学习。
（7）最完美的架构是把CPU 和GPU(或其他处理器)结合起来：未来，还会推出许多专门的领域所需的超强性能的处理器，但是CPU 是通用于各种设备，什么场景都可以适用。
（8） AR 成为AI 的眼睛，两者是互补、不可或缺：未来的AI 需要AR，未来的AR 也需要AI，可以将AR 比喻成AI 的眼睛。
2、按能力划分的三类人工智能：人工智能可以分为“弱人工智能”“强人工智能”和“超人工智能”三类。
3、从“人工+智能”向自主智能系统发展：当前人工智能领域的大量研究集中在深度学习，但是深度学习的局限是需要大量人工干预，比如人工设计深度神经网络模型、人工设定应用场景、人工采集和标注大量训练数据、用户需要人工适配智能系统等，非常费时费力。因此，科研人员开始关注减少人工干预的自主智能方法，提高机器智能对环境的自主学习能力。例如阿尔法狗系统的后续版本阿尔法元从零开始，通过自我对弈强化学习实现围棋、国际象棋、日本将棋的“通用棋类人工智能”。在人工智能系统的自动化设计方面，2017年谷歌提出的自动化学习系统（AutoML）试图通过自动创建机器学习系统降低人员成本。
4、人工智能领域的国际竞争将日益激烈：当前，人工智能领域的国际竞赛已经拉开帷幕，并且将日趋白热化。2018年4月，欧盟委员会计划2018—2020年在人工智能领域投资240亿美元；法国总统在2018年5月宣布《法国人工智能战略》，目的是迎接人工智能发展的新时代，使法国成为人工智能强国；2018年6月，日本《未来投资战略2018》重点推动物联网建设和人工智能的应用。
5、从专用智能向通用智能发展：如何实现从专用人工智能向通用人工智能的跨越式发展，既是下一代人工智能发展的必然趋势，也是研究与应用领域的重大挑战。2016年10月，美国国家科学技术委员会发布《国家人工智能研究与发展战略计划》，提出在美国的人工智能长期发展策略中要着重研究通用人工智能。阿尔法狗系统开发团队创始人戴密斯·哈萨比斯提出朝着“创造解决世界上一切问题的通用人工智能”这一目标前进。微软在2017年成立了通用人工智能实验室，众多感知、学习、推理、自然语言理解等方面的科学家参与其中。
6、从人工智能向人机混合智能发展：借鉴脑科学和认知科学的研究成果是人工智能的一个重要研究方向。人机混合智能旨在将人的作用或认知模型引入人工智能系统中，提升人工智能系统的性能，使人工智能成为人类智能的自然延伸和拓展，通过人机协同更加高效地解决复杂问题。在我国新一代人工智能规划和美国脑计划中，人机混合智能都是重要的研发方向。
7、人工智能主要应用领域：人工智能主要应用于手机、APP、各种智能穿戴设备，以及医疗、教育、金融行业、重工制造业等领域。
考向复习提示：生成式人工智能（AIGC）与大语言模型趋势
人工智能迎来生成式 AI（AIGC）历史拐点，以 ChatGPT、DeepSeek 为代表的基于 Transformer 架构的海量参数大语言模型（LLM），展现出惊人的上下文理解、常识推理、代码编写与多模态（文生图/文生视频，如 Sora）创造力；驱动人机交互迈向新纪元。
高频易错陷阱：大语言模型的“幻觉（Hallucination）”现象与科技伦理
专转本前沿科技常考考点：生成式大语言模型的底层原理是基于概率统计预测“下一个词出现的概率”，因此大模型并不真正理解事实逻辑，它会言之凿凿、语调自信地编造完全虚构的虚假事实、伪造不存在的书籍文献，这种现象在学术界被称为“AI 幻觉（Hallucination）”；因此严肃领域必须引入检索增强生成（RAG）进行知识纠偏！
考向复习提示：2025–2026 前沿同步：AI Agent、MCP 协议与具身智能
紧扣 **2025–2026 年**产业界三大核心关键词拓展认知（同时衔接教材 AI 伦理与合规考察）：
• AI Agent（自主智能体）：AI 正从被动问答工具升级为具备长期记忆、自主拆解长任务、自动纠错与多智能体协同的生产力主力；
• MCP 协议（Model Context Protocol，模型上下文协议）：最初由 Anthropic 推出并于 2025 年底捐赠给 Linux 基金会旗下开源组织，被誉为 AI 智能体连接外部数据库、本地文件与企业 API 的 USB-C 式统一标准接口；
• 具身智能（Embodied AI）：结合视觉-语言-动作（VLA）模型与世界模型，让大模型大脑真正装入人形机器人、四足机器人与工业机器人的物理身体，并在 **2026 年**迈入工业分拣、巡检及服务量产试点拐点；
• 法规底线合规：在公开发布生成式 AI 作品时，须严格遵守 2025 年 9 月 1 日施行的 GB 45438-2025 显式与隐式内容标识强制要求。$p2s_227$, $p2r_227${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: B6-6.3.3 人工智能未来发展趋势。", "题库补充：按能力划分的三类人工智能 (47题)", "题库补充：从“人工+智能”向自主智能系统发展 (14题)", "题库补充：人工智能领域的国际竞争将日益激烈 (13题)", "题库补充：从专用智能向通用智能发展 (11题)", "题库补充：从人工智能向人机混合智能发展 (10题)", "题库补充：人工智能主要应用领域 (10题)", "p2_timeliness_20261114"], "pages": [133], "spans": 20}$p2r_227$::jsonb, NOW());
  UPDATE kb_entry SET published_rev = 4, updated_at = NOW() WHERE node_id = 227;
END $$;

