DO $$
DECLARE
  v_actual INT;
  v_expected INT := 4;
BEGIN
  SELECT published_rev INTO v_actual FROM kb_entry WHERE node_id = 233 FOR UPDATE;
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock mismatch for node 233: expected %, got %', v_expected, v_actual;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref, created_at)
  VALUES (233, 5, $p2b_233$[{"t": "list", "id": "b7-7-2-1-b1", "imp": "core", "items": ["1、==以太坊==", "（1）==以太坊是一个开放的有智能合约功能的公共区块链平台，通过其专用加密货币以太币（Ether，简称“ETH”）提供以太虚拟机（Ethereum Virtual Machine，EVM）来处理去中心化合约应用。==", "（2）^^以太坊虚拟机(EVM)：以太坊中智能合约的运行环境。^^", "（3）^^以太坊使用场景：支付系统（数字货币交易，价值互换）、去中心化应用（黄金和股票的数字化应用、金融衍生品应用）等。^^", "2、^^以太坊核心架构^^", "（1）以太坊的整体架构为三层：==底层服务、核心层、顶层应用==。", "（2）有时候以太坊采用五层架构实现，从下到上分别是==数据层、 网络层、共识层、激励层、智能合约层==。", "3、区块链组成", "（1）==区块==，其实可以定义为记录一段时间内发生的交易和状态结果的数据结构，是对当前账本状态的一次共识。区块主要由==区块头、交易列表和叔区块头==三部分组成；", "（2）==区块头==包含：父块的散列值（ Prev Hash ）、叔区块的散列值（ Uncles Hash ）、状态树根散列值（ stateRoot ） 、交易树根散列值（ Transaction Root ） 、收据树根散列值（ Receipt Root ）、时间戳（ Timestamp ）、随机数（ Nonce ）等。", "（3）以太坊区块链上区块数据结构相对比特币的一个重大改变就是保存了三棵==Merkle 树根==，分别是==状态树、交易树和收据树==。", "（4）==交易列表==：交易列表是由矿工从交易池中选择收入区块中的一系列交易。", "（5）==叔区块头==：不在主链上的且被主链上的区块通过Uncles 字段收留进区块链的孤块叫做“叔区块” 。", "4、==共识机制==", "（1）==PoW 即通过计算工作量来证明你完成了相应的工作==（==Proof of Work 工作量证明==）", "POW 算法原理：节点通过工作结果不断地更换随机数来探寻合适的哈希值，当节点最先计算出合适的哈希值，它所打包的块如果通过其他共识节点的验证，则会被加入到区块链中。", "（2）==PoS 即基于网络参与者目前所持有的数字货币的数量和时间进行利益分配==，是一种对货币所有权的证明（ ==Proof of Stake 股权证明==）。算法类型：基于链的PoS 和BFT (Byzantine Fault Tolerant ，拜占庭容错）风格的PoS 。", "5、==账户==", "==（1）账户以地址为索引，地址由公钥衍生而来，取公钥的最后20 字节。==", "==（2）两种类型账户：外部账户和合约账户==", "^^①、外部账户（ Externally Owned Account, EOA ）由私钥来控制，是由用户实际控制的账户。^^", "^^②、合约账户是一个包含合约代码的账户。^^", "6、数据结构与存储", "（1）==区块、交易等数据最终都是存储在Level DB 数据库中==。==Level DB 数据库是一个键值对（ key-value ）数据库， key 一般与散列相关，value 则是存储内容的RLP（ Recursive Length Prefix，递归的长度前缀）编码。==", "（2）RLP(Recursive Length Prefix，递归的长度前缀)是一种编码规则，可用于编码任意嵌套的二进制数组数据。", "（3）==以太坊使用了MPT 树（Merkle Patricia Trie），作为数据组织形式==，用来组织管理用户的账户状态、交易信息等重要数据。", "（3）LevelDB 是键值对数据库（二进制），以太坊中共有三个LevelDB 数据库，分别是@@BlockDB（块头和交易） 、StateDB（账户的状态数据） 和ExtrasDB（收据信息和其他辅助信息）@@。", "7、==智能合约的优点与不足==：^^智能合约具有以下优点^^：", "① ^^高效的实时更新^^：==智能合约的执行不需要人为的第三方介入==，执行快捷且不可逆，能够在任何时候响应用户的请求，大大提升了交易效率。用户不必等待银行开门就能办理相关业务，只要通过网络即可方便快捷地完成。", "② ^^准确执行^^：==智能合约的所有条款和执行过程都是提前制定好的==，并在计算机的绝对控制下进行，因此执行结果准确无误，不会出现不可预料的结果，这正是传统合约制定和执行过程中所期望的；智能合约的准确执行得益于密码学的发展和区块链技术的发明。", "8、^^以太坊的五层体系架构^^：==通常把以太坊体系架构分为五层==：^^数据层、网络层、共识层、激励层和智能合约层^^。数据层负责区块与交易数据的组织、存储；网络层负责节点间的 P2P 通信与数据传播；共识层负责各节点状态的一致性；激励层通过奖励与惩罚维持网络运行；智能合约层提供合约的编写与执行环境。"], "title": "", "ordered": false}, {"t": "table", "id": "b7-7-2-1-t1", "imp": "core", "rows": [["相同点", "同属公有链、早期均采用 PoW 工作量证明、均内置加密数字货币", "同属公有链、初始架构采用 PoW 共识、内置以太币（ETH）"], ["图灵完备性与应用范围", "脚本语言非图灵完备，主要用于加密数字货币", "建立图灵完备底层系统，支持 EVM 虚拟机与智能合约及 DApp 生态"], ["平均出块时间", "约 `10 min`", "约 `15 s`（区块体更小）"], ["发行与增发机制", "总量上限恒定、按周期减半挖矿产出", "预挖矿机制（发布前产生约 7200 万枚用于众筹），之后每年相对固定增发"], ["孤块/叔区块奖励", "孤块被丢弃，无额外奖励", "==叔区块（Uncle Block）以及收留叔区块的主区块均获得额外奖励=="]], "title": "", "headers": ["对比维度", "比特币（Bitcoin，区块链 1.0）", "以太坊（Ethereum，区块链 2.0）"]}, {"t": "list", "id": "b7-7-2-1-m1", "imp": "core", "items": ["9、^^以太坊应用场景与数字人民币辨析^^：以太坊常用于支付互换与去中心化应用（DApp、金融衍生品、数字资产映射）等；@@我国央行数字人民币（e-CNY）采用了借鉴分布式账本与密码技术的混合技术架构（中心化管理 + 分布式账本/加密算法结合），并非开放公有链。@@", "10、^^以太坊三层 vs 五层/六层体系架构明细^^：以太坊整体可按==顶层应用（Solidity 智能合约、DApp、ENS、API）— 核心层（区块链交易/消息/Gas/三棵树、EVM、PoW/PoS 共识）— 底层服务（P2P 网络、LevelDB 数据库、密码学、分片）==三层划分；也常按五层/六层模型自下而上描述为==数据层 → 网络层 → 共识层 → 激励层 → 合约层 → 应用层==，其中@@激励层在公有链中不可或缺，但在无需代币的联盟链与私有链中为可选层@@。", "11、==智能合约的 5 大优点与 8 大现存问题==：==优点（5 项）==：① 高效实时更新（无需第三方中介全天候响应）；② 准确执行；③ 较低的人为干预风险（部署后不可违约篡改）；④ 去中心化权威（全网共识监督仲裁）；⑤ 较低运行成本。==问题（8 项）==：① 智能合约尚不“智能”（多为固定模板）；② 法律效力与合约法冲突的合法性问题；③ 合约代码漏洞引发的可信问题（需形式化验证）；④ 依赖外部数据源可能打破共识的外部信息问题；⑤ 多合约并发触发的同步与一致性问题；⑥ 复杂逻辑耗尽算力/死循环的安全性问题；⑦ 合约与建块耦合导致的性能问题；⑧ 业务模型问题（面向真实业务的建模工具尚不完善）。", "12、^^主流共识机制补全（DPoS 与 PBFT）^^：==DPoS（Delegated Proof of Stake，股份授权证明）==由持币者投票选出代理人代表出块以提升效率；==PBFT（Practical Byzantine Fault Tolerance，实用拜占庭容错）==于 ==1999 年由 MIT 的 Miguel Castro 和 Barbara Liskov 提出==，将拜占庭容错算法复杂度由指数级降至多项式级，使联盟链/许可链确定性共识成为现实。"], "title": "", "ordered": false}, {"h": 1000, "t": "img", "w": 1800, "id": "b7-7-2-1-img1", "alt": "以太坊三层体系结构图", "imp": "normal", "src": "/kb-assets/zhihu24/b721-eth-three-layer.png", "title": "", "caption": "以太坊三层体系结构（顶层应用 / 核心层 / 底层服务）"}, {"h": 960, "t": "img", "w": 1880, "id": "b7-7-2-1-img2", "alt": "以太坊全网状态外部账户与合约账户对照图", "imp": "normal", "src": "/kb-assets/zhihu24/b721-eth-accounts.png", "title": "", "caption": "以太坊全网状态：外部账户（EOA）与合约账户（Contract Account）对照"}, {"t": "callout", "id": "b7-7-2-1-b2", "imp": "core", "kind": "tip", "text": "以太坊由俄罗斯程序员维塔利克·布特林（Vitalik Buterin，V神）于 2013 年提出，被誉为“全球去中心化计算机”；它引入了以太坊虚拟机（EVM），允许开发者使用 Solidity 语言编写并在区块链上部署执行==“智能合约（Smart Contract）”==；以太币（ETH）作为驱动合约运行计算的“燃料费（Gas）”。", "title": "考向复习提示：以太坊（Ethereum）与智能合约运行机制"}, {"t": "callout", "id": "b7-7-2-1-b3", "imp": "core", "kind": "trap", "text": "专转本高频单选题：==智能合约本质上是一段预先部署在区块链上的、具备“条件满足即强制自动执行”特性的计算机程序代码==；以太坊相比比特币最大的颠覆在于其支持图灵完备性（支持循环与任意复杂计算逻辑），智能合约一旦部署在链上，任何单一权威机构都无法擅自单方面修改或强行撤回！", "title": "高频易错陷阱：智能合约的本质与图灵完备性考点"}, {"id": "b7-7-2-1-p2-sync-warn", "t": "callout", "kind": "warn", "title": "重点注意事项：2025–2026 实况纠偏：以太坊早已完成 PoW 向 PoS 全面迁移", "text": "教材成书较早，介绍以太坊时多并列讲解 `PoW` 与 `PoS` 共识（考试问及基础共识概念或三棵 `Merkle` 树、`LevelDB` 等架构术语时仍按正文回答），但需知晓实际主网早已完成三次里程碑升级：\n• ==2022 年 9 月 `The Merge`（合并升级）==：以太坊主网正式废除高耗能挖矿，全面切换为 ==`PoS`（权益证明）共识机制==，整网能耗下降超 99%；\n• ==2024 年 3 月 `Dencun` 升级（`EIP-4844`）==：引入专供二层扩容（Layer 2 Rollup）使用的临时数据块 ==`Blob`==，将 Arbitrum/Optimism/Base 等二层网络手续费大幅降至数美分乃至更低；\n• ==2025 年 5 月 `Pectra` 升级（`EIP-7702` 等）==：允许普通外部账户（`EOA`）在交易期间临时执行智能合约代码（推进账户抽象与免手续费代付体验），并将单验证者最大有效质押上限由 `32 ETH` 提升至 ==`2048 ETH`（`EIP-7251`）==。", "imp": "core"}]$p2b_233$::jsonb, '', $p2s_233$B7-7.2.1 以太坊技术框架。
1、以太坊
（1）以太坊是一个开放的有智能合约功能的公共区块链平台，通过其专用加密货币以太币（Ether，简称“ETH”）提供以太虚拟机（Ethereum Virtual Machine，EVM）来处理去中心化合约应用。
（2）以太坊虚拟机(EVM)：以太坊中智能合约的运行环境。
（3）以太坊使用场景：支付系统（数字货币交易，价值互换）、去中心化应用（黄金和股票的数字化应用、金融衍生品应用）等。
2、以太坊核心架构
（1）以太坊的整体架构为三层：底层服务、核心层、顶层应用。
（2）有时候以太坊采用五层架构实现，从下到上分别是数据层、 网络层、共识层、激励层、智能合约层。
3、区块链组成
（1）区块，其实可以定义为记录一段时间内发生的交易和状态结果的数据结构，是对当前账本状态的一次共识。区块主要由区块头、交易列表和叔区块头三部分组成；
（2）区块头包含：父块的散列值（ Prev Hash ）、叔区块的散列值（ Uncles Hash ）、状态树根散列值（ stateRoot ） 、交易树根散列值（ Transaction Root ） 、收据树根散列值（ Receipt Root ）、时间戳（ Timestamp ）、随机数（ Nonce ）等。
（3）以太坊区块链上区块数据结构相对比特币的一个重大改变就是保存了三棵Merkle 树根，分别是状态树、交易树和收据树。
（4）交易列表：交易列表是由矿工从交易池中选择收入区块中的一系列交易。
（5）叔区块头：不在主链上的且被主链上的区块通过Uncles 字段收留进区块链的孤块叫做“叔区块” 。
4、共识机制
（1）PoW 即通过计算工作量来证明你完成了相应的工作（Proof of Work 工作量证明）
POW 算法原理：节点通过工作结果不断地更换随机数来探寻合适的哈希值，当节点最先计算出合适的哈希值，它所打包的块如果通过其他共识节点的验证，则会被加入到区块链中。
（2）PoS 即基于网络参与者目前所持有的数字货币的数量和时间进行利益分配，是一种对货币所有权的证明（ Proof of Stake 股权证明）。算法类型：基于链的PoS 和BFT (Byzantine Fault Tolerant ，拜占庭容错）风格的PoS 。
5、账户
（1）账户以地址为索引，地址由公钥衍生而来，取公钥的最后20 字节。
（2）两种类型账户：外部账户和合约账户
①、外部账户（ Externally Owned Account, EOA ）由私钥来控制，是由用户实际控制的账户。
②、合约账户是一个包含合约代码的账户。
6、数据结构与存储
（1）区块、交易等数据最终都是存储在Level DB 数据库中。Level DB 数据库是一个键值对（ key-value ）数据库， key 一般与散列相关，value 则是存储内容的RLP（ Recursive Length Prefix，递归的长度前缀）编码。
（2）RLP(Recursive Length Prefix，递归的长度前缀)是一种编码规则，可用于编码任意嵌套的二进制数组数据。
（3）以太坊使用了MPT 树（Merkle Patricia Trie），作为数据组织形式，用来组织管理用户的账户状态、交易信息等重要数据。
（3）LevelDB 是键值对数据库（二进制），以太坊中共有三个LevelDB 数据库，分别是BlockDB（块头和交易） 、StateDB（账户的状态数据） 和ExtrasDB（收据信息和其他辅助信息）。
7、智能合约的优点与不足：智能合约具有以下优点：
① 高效的实时更新：智能合约的执行不需要人为的第三方介入，执行快捷且不可逆，能够在任何时候响应用户的请求，大大提升了交易效率。用户不必等待银行开门就能办理相关业务，只要通过网络即可方便快捷地完成。
② 准确执行：智能合约的所有条款和执行过程都是提前制定好的，并在计算机的绝对控制下进行，因此执行结果准确无误，不会出现不可预料的结果，这正是传统合约制定和执行过程中所期望的；智能合约的准确执行得益于密码学的发展和区块链技术的发明。
8、以太坊的五层体系架构：通常把以太坊体系架构分为五层：数据层、网络层、共识层、激励层和智能合约层。数据层负责区块与交易数据的组织、存储；网络层负责节点间的 P2P 通信与数据传播；共识层负责各节点状态的一致性；激励层通过奖励与惩罚维持网络运行；智能合约层提供合约的编写与执行环境。
对比维度 比特币（Bitcoin，区块链 1.0） 以太坊（Ethereum，区块链 2.0）
相同点 同属公有链、早期均采用 PoW 工作量证明、均内置加密数字货币 同属公有链、初始架构采用 PoW 共识、内置以太币（ETH）
图灵完备性与应用范围 脚本语言非图灵完备，主要用于加密数字货币 建立图灵完备底层系统，支持 EVM 虚拟机与智能合约及 DApp 生态
平均出块时间 约 10 min 约 15 s（区块体更小）
发行与增发机制 总量上限恒定、按周期减半挖矿产出 预挖矿机制（发布前产生约 7200 万枚用于众筹），之后每年相对固定增发
孤块/叔区块奖励 孤块被丢弃，无额外奖励 叔区块（Uncle Block）以及收留叔区块的主区块均获得额外奖励
9、以太坊应用场景与数字人民币辨析：以太坊常用于支付互换与去中心化应用（DApp、金融衍生品、数字资产映射）等；我国央行数字人民币（e-CNY）采用了借鉴分布式账本与密码技术的混合技术架构（中心化管理 + 分布式账本/加密算法结合），并非开放公有链。
10、以太坊三层 vs 五层/六层体系架构明细：以太坊整体可按顶层应用（Solidity 智能合约、DApp、ENS、API）— 核心层（区块链交易/消息/Gas/三棵树、EVM、PoW/PoS 共识）— 底层服务（P2P 网络、LevelDB 数据库、密码学、分片）三层划分；也常按五层/六层模型自下而上描述为数据层 → 网络层 → 共识层 → 激励层 → 合约层 → 应用层，其中激励层在公有链中不可或缺，但在无需代币的联盟链与私有链中为可选层。
11、智能合约的 5 大优点与 8 大现存问题：优点（5 项）：① 高效实时更新（无需第三方中介全天候响应）；② 准确执行；③ 较低的人为干预风险（部署后不可违约篡改）；④ 去中心化权威（全网共识监督仲裁）；⑤ 较低运行成本。问题（8 项）：① 智能合约尚不“智能”（多为固定模板）；② 法律效力与合约法冲突的合法性问题；③ 合约代码漏洞引发的可信问题（需形式化验证）；④ 依赖外部数据源可能打破共识的外部信息问题；⑤ 多合约并发触发的同步与一致性问题；⑥ 复杂逻辑耗尽算力/死循环的安全性问题；⑦ 合约与建块耦合导致的性能问题；⑧ 业务模型问题（面向真实业务的建模工具尚不完善）。
12、主流共识机制补全（DPoS 与 PBFT）：DPoS（Delegated Proof of Stake，股份授权证明）由持币者投票选出代理人代表出块以提升效率；PBFT（Practical Byzantine Fault Tolerance，实用拜占庭容错）于 1999 年由 MIT 的 Miguel Castro 和 Barbara Liskov 提出，将拜占庭容错算法复杂度由指数级降至多项式级，使联盟链/许可链确定性共识成为现实。
以太坊三层体系结构（顶层应用 / 核心层 / 底层服务）
以太坊全网状态：外部账户（EOA）与合约账户（Contract Account）对照
考向复习提示：以太坊（Ethereum）与智能合约运行机制
以太坊由俄罗斯程序员维塔利克·布特林（Vitalik Buterin，V神）于 2013 年提出，被誉为“全球去中心化计算机”；它引入了以太坊虚拟机（EVM），允许开发者使用 Solidity 语言编写并在区块链上部署执行“智能合约（Smart Contract）”；以太币（ETH）作为驱动合约运行计算的“燃料费（Gas）”。
高频易错陷阱：智能合约的本质与图灵完备性考点
专转本高频单选题：智能合约本质上是一段预先部署在区块链上的、具备“条件满足即强制自动执行”特性的计算机程序代码；以太坊相比比特币最大的颠覆在于其支持图灵完备性（支持循环与任意复杂计算逻辑），智能合约一旦部署在链上，任何单一权威机构都无法擅自单方面修改或强行撤回！
重点注意事项：2025–2026 实况纠偏：以太坊早已完成 PoW 向 PoS 全面迁移
教材成书较早，介绍以太坊时多并列讲解 PoW 与 PoS 共识（考试问及基础共识概念或三棵 Merkle 树、LevelDB 等架构术语时仍按正文回答），但需知晓实际主网早已完成三次里程碑升级：
• 2022 年 9 月 The Merge（合并升级）：以太坊主网正式废除高耗能挖矿，全面切换为 PoS（权益证明）共识机制，整网能耗下降超 99%；
• 2024 年 3 月 Dencun 升级（EIP-4844）：引入专供二层扩容（Layer 2 Rollup）使用的临时数据块 Blob，将 Arbitrum/Optimism/Base 等二层网络手续费大幅降至数美分乃至更低；
• 2025 年 5 月 Pectra 升级（EIP-7702 等）：允许普通外部账户（EOA）在交易期间临时执行智能合约代码（推进账户抽象与免手续费代付体验），并将单验证者最大有效质押上限由 32 ETH 提升至 2048 ETH（EIP-7251）。$p2s_233$, $p2r_233${"pdf": "理论复习.pdf", "extra": ["考纲三级节点: B7-7.2.1 以太坊技术框架。", "题库补充：智能合约的优点与不足 (27题)", "题库补充：以太坊的五层体系架构 (8题)", "p1_refine_20261114", "p2_timeliness_20261114"], "pages": [135, 136], "spans": 41}$p2r_233$::jsonb, NOW());
