END $$;

-- 提交前数据库级完整性校验（无 \r 残留、29 个目标节点版本准确更新）
DO $$
DECLARE
  v_cr_cnt INT;
  v_p2_cnt INT;
BEGIN
  SELECT count(*) INTO v_cr_cnt
    FROM kb_entry e JOIN kb_revision r ON r.node_id = e.node_id AND r.rev_no = e.published_rev
   WHERE e.status = 'published' AND r.search_text LIKE '%' || E'\r' || '%';
  IF v_cr_cnt > 0 THEN
    RAISE EXCEPTION 'Found % published nodes with CR in search_text', v_cr_cnt;
  END IF;

  SELECT count(*) INTO v_p2_cnt
    FROM kb_entry
   WHERE status = 'published' AND ((node_id = 40 AND published_rev = 8) OR (node_id = 43 AND published_rev = 5) OR (node_id = 50 AND published_rev = 10) OR (node_id = 51 AND published_rev = 11) OR (node_id = 72 AND published_rev = 4) OR (node_id = 78 AND published_rev = 6) OR (node_id = 98 AND published_rev = 7) OR (node_id = 113 AND published_rev = 5) OR (node_id = 136 AND published_rev = 5) OR (node_id = 137 AND published_rev = 5) OR (node_id = 165 AND published_rev = 4) OR (node_id = 168 AND published_rev = 4) OR (node_id = 173 AND published_rev = 6) OR (node_id = 177 AND published_rev = 3) OR (node_id = 182 AND published_rev = 5) OR (node_id = 187 AND published_rev = 5) OR (node_id = 191 AND published_rev = 4) OR (node_id = 195 AND published_rev = 4) OR (node_id = 203 AND published_rev = 5) OR (node_id = 214 AND published_rev = 4) OR (node_id = 218 AND published_rev = 5) OR (node_id = 225 AND published_rev = 4) OR (node_id = 227 AND published_rev = 4) OR (node_id = 231 AND published_rev = 6) OR (node_id = 233 AND published_rev = 5) OR (node_id = 237 AND published_rev = 7) OR (node_id = 312 AND published_rev = 5) OR (node_id = 327 AND published_rev = 4) OR (node_id = 338 AND published_rev = 5));
  IF v_p2_cnt <> 29 THEN
    RAISE EXCEPTION 'Expected 29 updated P2 nodes, got %', v_p2_cnt;
  END IF;
END $$;

COMMIT;
